insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e2000000-0000-0000-0000-000000000001', 'ukmla', '00a800d3-4c40-414b-ab51-f4cb5710ab52',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e2000000-0000-0000-0000-000000000001', 'A', 'Arrange an urgent CT scan of the abdomen to look for a reversible cause of her deterioration', false, 'Ruled out because this clinical picture is a recognised pattern of the dying phase in a patient with known incurable, advanced malignancy; subjecting her to transfer for imaging would not be in her best interests and would not change management.', 1),
('e2000000-0000-0000-0000-000000000001', 'B', 'Start intravenous fluids and broad-spectrum antibiotics to treat probable sepsis', false, 'Ruled out because there is nothing here specifically pointing to sepsis, and escalating invasive treatment in a patient who is dying of known advanced cancer is not appropriate without evidence it would reverse her decline or align with her wishes.', 2),
('e2000000-0000-0000-0000-000000000001', 'C', 'Continue all current medications and routine four-hourly observations unchanged', false, 'Ruled out because continuing full monitoring and non-essential medications in a dying patient causes unnecessary burden; medicines should be rationalised to those providing comfort.', 3),
('e2000000-0000-0000-0000-000000000001', 'D', 'Tell the family nothing can be predicted and that no changes to her care are needed', false, 'Ruled out because open, honest communication about the likelihood that she is dying is essential for the family to prepare, and a proactive change in the care plan (anticipatory medicines, deprescribing) is required.', 4),
('e2000000-0000-0000-0000-000000000001', 'E', 'Recognise that she is likely entering the dying phase, explain this sensitively to the family, and switch her care plan to comfort-focused measures with anticipatory subcutaneous medications', true, 'Correct. The combination of progressive drowsiness, reduced oral intake, Cheyne-Stokes breathing and peripheral mottling are recognised features of the dying phase; the priority is honest communication with the family and a switch to symptom-focused, comfort care with anticipatory medicines prescribed.', 5),
('e2000000-0000-0000-0000-000000000002', 'A', $x$Document the discussion, confirm the decision reflects the patient's informed wishes, and complete the DNACPR form as a medical decision made in conjunction with the patient$x$, true, 'Correct. A DNACPR decision is fundamentally a clinical decision, but where a patient has capacity their wishes must be central to that decision and discussed with them sensitively; here the patient has expressed a clear, informed preference against CPR, which should be documented and respected.', 1),
('e2000000-0000-0000-0000-000000000002', 'B', $x$Ask the patient's next of kin to sign the DNACPR form since they must legally consent to it$x$, false, 'Ruled out because relatives cannot give or withhold consent for a DNACPR decision when the patient has capacity; the decision belongs to the patient in discussion with the clinical team.', 2),
('e2000000-0000-0000-0000-000000000002', 'C', 'Refuse to discuss resuscitation status because it may cause the patient psychological distress', false, 'Ruled out because withholding an appropriate, sensitively handled conversation about resuscitation from a patient with capacity denies them the ability to express their own wishes, and case law requires this discussion unless it would cause real harm.', 3),
('e2000000-0000-0000-0000-000000000002', 'D', 'Tell the patient that CPR will always be attempted regardless of his wishes because he has a treatable exacerbation', false, 'Ruled out because a patient with capacity has the right to have their wishes considered in this decision, and CPR is not a treatment that must be offered irrespective of expressed preference or likely benefit.', 4),
('e2000000-0000-0000-0000-000000000002', 'E', 'Delay any DNACPR discussion until he loses capacity, as it is easier to decide with the family alone', false, 'Ruled out because best practice is to have this conversation while the patient retains capacity, so that their own wishes directly inform the decision rather than being inferred later.', 5),
('e2000000-0000-0000-0000-000000000003', 'A', 'Proceed directly to whichever treatment the consultant personally believes is best, without further process', false, $x$Ruled out because a best interests decision must follow a structured process considering the patient's known wishes, values and circumstances, and an IMCA referral is specifically required in this situation of no available family.$x$, 1),
('e2000000-0000-0000-0000-000000000003', 'B', 'Withhold all treatment until a court order authorising treatment is obtained', false, 'Ruled out because routine best interests decisions, including for patients without family, do not require court authorisation; the Court of Protection is reserved for cases of serious disagreement or highly contentious decisions.', 2),
('e2000000-0000-0000-0000-000000000003', 'C', 'Make a best interests decision under the Mental Capacity Act, involving an Independent Mental Capacity Advocate (IMCA) since no family or attorney is available', true, $x$Correct. When a patient lacks capacity and has no family, friends, attorney or deputy to consult, the Mental Capacity Act requires referral to an Independent Mental Capacity Advocate to represent the patient's views before a best interests decision is made about serious medical treatment.$x$, 3),
('e2000000-0000-0000-0000-000000000003', 'D', 'Ask the nursing home staff who know her to make the final decision on her behalf', false, $x$Ruled out because care staff can contribute helpful information about the patient's usual wishes and preferences, but the responsibility for a best interests decision about medical treatment rests with the treating clinician, informed by an IMCA where required.$x$, 4),
('e2000000-0000-0000-0000-000000000003', 'E', 'Delay treatment decisions indefinitely until a relative can be found', false, 'Ruled out because a best interests decision must still be made in a timely way for someone acutely unwell, using the IMCA safeguard rather than waiting indefinitely for family to be located.', 5),
('e2000000-0000-0000-0000-000000000004', 'A', 'Reassure him that nothing can be planned in advance because his condition may change', false, 'Ruled out because advance care planning is specifically designed to anticipate future deterioration and record preferences in advance, and heart failure trajectories, while variable, do not preclude this discussion.', 1),
('e2000000-0000-0000-0000-000000000004', 'B', 'Refer him immediately to a hospice for inpatient admission', false, 'Ruled out because there is no indication he needs inpatient hospice admission now; the appropriate step is proactive planning and community support to enable care and death at home if that remains his preference.', 2),
('e2000000-0000-0000-0000-000000000004', 'C', 'Increase his diuretic dose and review again in six months without further discussion', false, 'Ruled out because this addresses only pharmacological management and ignores his explicitly stated wish to discuss future care preferences, which should be documented and acted upon promptly.', 3),
('e2000000-0000-0000-0000-000000000004', 'D', 'Initiate an advance care planning discussion, documenting his preferences (such as through a ReSPECT process) and sharing this with relevant teams including out-of-hours and ambulance services', true, 'Correct. This is an appropriate opportunity for proactive advance care planning; documenting his preferences for future care and resuscitation status (for example via a ReSPECT form) and sharing this across services ensures his wishes are respected if he deteriorates, including out of hours.', 4),
('e2000000-0000-0000-0000-000000000004', 'E', 'Tell him that resuscitation and hospital admission decisions cannot be discussed until he is admitted as an emergency', false, 'Ruled out because these conversations are best had proactively, in a planned, unhurried way, rather than only in an emergency when the patient may lack capacity or capacity to discuss calmly.', 5),
('e2000000-0000-0000-0000-000000000005', 'A', 'Withdraw the nasogastric feeding immediately since the medical team believes recovery is impossible', false, $x$Ruled out because unilateral withdrawal without a proper best interests process, especially where family disagree, risks failing to reflect the patient's own values and bypasses necessary safeguards for this serious decision.$x$, 1),
('e2000000-0000-0000-0000-000000000005', 'B', $x$Hold a formal best interests meeting involving the family and the multidisciplinary team, and seek legal or ethics advice given the family's disagreement, before any decision to withdraw nutrition$x$, true, 'Correct. Withdrawing clinically assisted nutrition and hydration is a serious, irreversible decision; where there is disagreement among those close to the patient, a structured best interests process involving the whole multidisciplinary team, with legal or clinical ethics input, is required before proceeding.', 2),
('e2000000-0000-0000-0000-000000000005', 'C', 'Continue nasogastric feeding indefinitely until every family member agrees, regardless of the clinical situation', false, $x$Ruled out because prolonged treatment purely to avoid difficult conversations does not serve the patient's best interests when clinical assessment concludes there is no prospect of recovery; unanimous family agreement is not a legal requirement for the decision to proceed.$x$, 3),
('e2000000-0000-0000-0000-000000000005', 'D', 'Ask the family to vote and follow the majority view', false, $x$Ruled out because best interests decisions are not resolved by family vote; they require a structured clinical and ethical assessment of the patient's overall best interests, informed by family input on the patient's known wishes and values.$x$, 4),
('e2000000-0000-0000-0000-000000000005', 'E', 'Transfer the decision entirely to the hospital chaplaincy team', false, 'Ruled out because while spiritual or chaplaincy support can be valuable to the family, the decision itself is a clinical and legal one requiring a best interests process, not one delegated to chaplaincy.', 5),
('e2000000-0000-0000-0000-000000000006', 'A', 'Insist that intravenous fluids must be started immediately because withholding them constitutes neglect', false, 'Ruled out because clinically assisted hydration is not automatically indicated in the dying phase; it is a clinical decision balanced against risks, not a mandatory intervention, and withholding it after appropriate assessment is not neglect.', 1),
('e2000000-0000-0000-0000-000000000006', 'B', 'Tell the daughter that mouth care is irrelevant once oral intake has stopped', false, 'Ruled out because regular mouth care remains important for comfort in dying patients regardless of hydration status, and dismissing this ignores an important comfort measure.', 2),
('e2000000-0000-0000-0000-000000000006', 'C', $x$State that hydration decisions are solely the family's to make and defer entirely to their wishes without clinical input$x$, false, 'Ruled out because this remains a clinical decision made collaboratively with the family, incorporating clinical judgement about likely benefit and harm, not one handed over entirely without medical guidance.', 3),
('e2000000-0000-0000-0000-000000000006', 'D', 'Explain that a trial of clinically assisted hydration can be considered if thought to relieve symptoms such as thirst or delirium, but that it also carries risks such as fluid overload and increased secretions in a dying patient, and is not guaranteed to prolong comfort', true, 'Correct. Clinically assisted hydration in the dying phase is an individualised decision balancing potential symptomatic benefit (for example, if hydration might relieve thirst or terminal delirium) against risks such as pulmonary oedema, peripheral oedema, and increased respiratory secretions; a clear, sensitive explanation to the family supports shared decision-making.', 4),
('e2000000-0000-0000-0000-000000000006', 'E', 'Refuse to discuss the topic further as it is too distressing to raise', false, 'Ruled out because sensitive, honest discussion of hydration decisions at the end of life is an important part of supporting the family and should not be avoided.', 5),
('e2000000-0000-0000-0000-000000000007', 'A', 'Reassure the family that this is simply the expected dying phase and no treatment is needed', false, 'Ruled out because hypercalcaemia is a recognised reversible cause of this clinical picture, and treating it may improve his symptoms and function; assuming irreversibility without addressing it risks missing a treatable contributor.', 1),
('e2000000-0000-0000-0000-000000000007', 'B', 'Start a syringe driver with anticipatory medications and stop all other treatment immediately', false, 'Ruled out because this jumps to comfort-only measures without first considering whether the deterioration might be reversible, which is not appropriate when a treatable cause has been identified.', 2),
('e2000000-0000-0000-0000-000000000007', 'C', 'Ignore the calcium result as it is unlikely to be clinically significant in advanced cancer', false, 'Ruled out because a corrected calcium of 3.4 mmol/L is significantly elevated and a recognised cause of confusion and drowsiness that often responds to treatment.', 3),
('e2000000-0000-0000-0000-000000000007', 'D', 'Arrange discharge home immediately without addressing the biochemical abnormality', false, 'Ruled out because discharging a confused, drowsy patient with an untreated, potentially correctable metabolic abnormality is unsafe and does not serve his best interests.', 4),
('e2000000-0000-0000-0000-000000000007', 'E', 'Treat the hypercalcaemia (with intravenous fluids and a bisphosphonate) as a potentially reversible cause of his deterioration before assuming he is imminently dying', true, $x$Correct. Severe hypercalcaemia of malignancy can mimic the dying phase, causing confusion, drowsiness and constipation, but is often reversible with rehydration and bisphosphonate therapy; this should be treated (if consistent with the patient's wishes and overall prognosis) before concluding the deterioration is irreversible.$x$, 5),
('e2000000-0000-0000-0000-000000000008', 'A', 'Give a precise number of weeks or months so she has a clear answer', false, 'Ruled out because prognosis in advanced cancer is inherently uncertain, and giving an artificially precise figure can be misleading and distressing if inaccurate; honest acknowledgement of uncertainty is preferred.', 1),
('e2000000-0000-0000-0000-000000000008', 'B', 'Tell her this question is best avoided and change the subject to something more positive', false, $x$Ruled out because avoiding a patient's direct, important question dismisses her autonomy and need for information, and is not compassionate or appropriate communication practice.$x$, 2),
('e2000000-0000-0000-0000-000000000008', 'C', 'Acknowledge her distress, check what she already understands and wants to know, and give honest information about the uncertainty of prognosis while offering to involve the palliative care team for ongoing support', true, $x$Correct. Good practice in breaking bad news involves acknowledging emotion, exploring the patient's own understanding and information needs before giving further detail, and being honest about prognostic uncertainty, while ensuring ongoing support such as specialist palliative care input is offered.$x$, 3),
('e2000000-0000-0000-0000-000000000008', 'D', 'Explain that only the consultant can discuss prognosis and that she must wait for their next visit', false, $x$Ruled out because while complex prognostic discussions may need senior input, a junior doctor should not simply deflect a distressed patient's question without acknowledging her feelings and finding out what she needs right now.$x$, 4),
('e2000000-0000-0000-0000-000000000008', 'E', 'Reassure her that everything will be fine and that she should not worry', false, 'Ruled out because false reassurance is dishonest and undermines trust; it does not respect her right to accurate information about her condition.', 5),
('e2000000-0000-0000-0000-000000000009', 'A', 'Attend to verify death by confirming absence of pulse, heart sounds and respiratory effort and fixed dilated pupils, documenting the time and findings in the notes', true, 'Correct. Verification of death (confirming that death has occurred) is a task an FY1 doctor is expected to perform competently, involving checks such as absence of central pulse, heart sounds, breath sounds and pupillary responses, with clear documentation.', 1),
('e2000000-0000-0000-0000-000000000009', 'B', $x$Refuse to attend because verifying death is not part of a junior doctor's role$x$, false, 'Ruled out because verification of death is a standard, expected competency for junior doctors and should not be refused when appropriately trained.', 2),
('e2000000-0000-0000-0000-000000000009', 'C', 'Immediately complete and sign the Medical Certificate of Cause of Death without examining the patient', false, 'Ruled out because verification of death (confirming the patient has died) is a separate step from certification (completing the formal cause of death certificate), and the patient must first be examined to confirm death has occurred.', 3),
('e2000000-0000-0000-0000-000000000009', 'D', 'Call the coroner immediately as all hospital deaths must be reported', false, 'Ruled out because an expected death from a recognised progressive illness under ongoing medical care does not automatically require coroner referral; only certain categories of death (for example unexpected, unexplained, or related to procedures) require this.', 4),
('e2000000-0000-0000-0000-000000000009', 'E', 'Wait until the following morning to attend, as verification of death is not urgent', false, 'Ruled out because verification of death should be carried out promptly to support the family and appropriate next steps, rather than delayed unnecessarily.', 5),
('e2000000-0000-0000-0000-000000000010', 'A', 'Tell the family that home death is not possible without a hospice bed being available first', false, 'Ruled out because home is a valid and achievable preferred place of care with appropriate community support, and hospice admission is not a prerequisite for dying at home.', 1),
('e2000000-0000-0000-0000-000000000010', 'B', 'Arrange an urgent fast-track continuing healthcare assessment and referral to the community palliative care and district nursing teams to support discharge home', true, 'Correct. When a patient with a clearly limited prognosis wishes to be cared for and die at home, an expedited (fast-track) continuing healthcare funding assessment along with referral to community palliative care and district nursing services allows rapid discharge with appropriate support in place.', 2),
('e2000000-0000-0000-0000-000000000010', 'C', 'Delay discharge planning until her condition further deteriorates', false, 'Ruled out because planning should begin promptly given her limited prognosis and expressed wishes, to avoid her dying in hospital against her preference due to delayed arrangements.', 3),
('e2000000-0000-0000-0000-000000000010', 'D', 'Advise the family that full-time hospital care is safer and try to dissuade her from going home', false, 'Ruled out because with appropriate community and district nursing support, home care is often both safe and achievable, and her clearly expressed preference should be supported rather than discouraged.', 4),
('e2000000-0000-0000-0000-000000000010', 'E', 'Discharge her home immediately with no additional support arranged', false, $x$Ruled out because discharging her without arranging community palliative care, district nursing and appropriate funding risks an unsafe, unsupported discharge and failure to meet the family's needs.$x$, 5),
('e2000000-0000-0000-0000-000000000011', 'A', 'Refer to the specialist palliative care team for input on complex symptom control and psychosocial support for the patient and family', true, 'Correct. Specialist palliative care referral is appropriate when symptoms remain difficult to control despite standard measures, or when there is significant psychological or family distress requiring specialist multidisciplinary input beyond generalist management.', 1),
('e2000000-0000-0000-0000-000000000011', 'B', 'Continue increasing the opioid dose repeatedly without specialist input or further assessment', false, 'Ruled out because persistently escalating opioids without reassessing the cause of pain or considering specialist input risks toxicity without addressing complex, multifactorial symptoms.', 2),
('e2000000-0000-0000-0000-000000000011', 'C', 'Tell the family that nothing further can be done for his pain', false, 'Ruled out because specialist palliative care input often identifies additional strategies for complex pain and distress; concluding nothing more can help is inaccurate and unhelpfully final.', 3),
('e2000000-0000-0000-0000-000000000011', 'D', 'Discharge him home with no further follow-up since his cancer is untreatable', false, 'Ruled out because ongoing symptom control and psychosocial needs still require active management and follow-up, irrespective of the cancer itself being untreatable.', 4),
('e2000000-0000-0000-0000-000000000011', 'E', 'Refer only to psychology services and not to palliative care', false, 'Ruled out because while psychological support may be valuable, his complex physical symptom control needs specifically warrant specialist palliative care review, which can coordinate a range of psychosocial and physical interventions.', 5),
('e2000000-0000-0000-0000-000000000012', 'A', 'Follow the wishes of whichever child is more insistent', false, $x$Ruled out because DNACPR decisions are not resolved by which family member argues more forcefully; they are based on clinical judgement about likely success and the patient's best interests, informed by, but not dictated by, family views.$x$, 1),
('e2000000-0000-0000-0000-000000000012', 'B', 'Perform CPR if the cardiac arrest occurs, because one relative disagrees with the DNACPR decision', false, $x$Ruled out because a properly made DNACPR decision, based on clinical judgement that CPR would not succeed or would not be in the patient's best interests, should be followed regardless of a relative's objection; families cannot mandate a treatment judged clinically inappropriate.$x$, 2),
('e2000000-0000-0000-0000-000000000012', 'C', 'Escalate immediately to the police to mediate the family dispute', false, 'Ruled out because this is a clinical and ethical decision-making issue, not a matter for police involvement; appropriate escalation would be to a senior clinician, and clinical ethics support if needed.', 3),
('e2000000-0000-0000-0000-000000000012', 'D', 'Refuse to make any decision until the children reach agreement themselves', false, $x$Ruled out because the clinical team is responsible for making an appropriate, timely decision in the patient's best interests; it should not be indefinitely deferred pending family consensus.$x$, 4),
('e2000000-0000-0000-0000-000000000012', 'E', 'Explain to both children that the DNACPR decision is a medical judgement about whether CPR would be successful or in his best interests, made by the clinical team taking their views into account, not one that requires family consensus or consent', true, $x$Correct. Where CPR is judged unlikely to succeed or not in the patient's best interests, DNACPR is a clinical decision; family members should be consulted and informed sensitively, but the decision does not require their agreement or consent, and family disagreement does not obligate attempting CPR that is not clinically appropriate.$x$, 5),
('e2000000-0000-0000-0000-000000000013', 'A', 'Contact the niece repeatedly and insist she make the decision despite her stated unwillingness', false, 'Ruled out because a family member who has explicitly declined involvement should not be coerced into making the decision; where no appropriate person is available or willing, an IMCA must be involved instead.', 1),
('e2000000-0000-0000-0000-000000000013', 'B', 'Allow the surgical team to proceed with surgery unilaterally since they have the most direct clinical role', false, 'Ruled out because unilateral decision-making by one team, without proper best interests process and appropriate advocacy input, is inappropriate in a genuinely disputed, high-stakes decision for a patient lacking capacity.', 2),
('e2000000-0000-0000-0000-000000000013', 'C', $x$Refer for an Independent Mental Capacity Advocate (IMCA), since there is no attorney and no family able or willing to be consulted, and hold a formal best interests discussion between the surgical and palliative care teams incorporating the IMCA's input$x$, true, $x$Correct. As the niece has declined involvement and there is no attorney or other appropriate person to consult, an IMCA must be involved in this best interests decision about serious medical treatment; given genuine disagreement between specialties, a structured multidisciplinary best interests discussion incorporating the IMCA's input is required before proceeding.$x$, 3),
('e2000000-0000-0000-0000-000000000013', 'D', 'Delay any decision until she regains capacity, however long that takes', false, 'Ruled out because bowel obstruction is a time-sensitive condition; decisions about her care must be made promptly using proper best interests processes, not delayed indefinitely.', 4),
('e2000000-0000-0000-0000-000000000013', 'E', 'Make the decision based solely on what is likely to be the cheapest treatment option', false, $x$Ruled out because best interests decisions must be based on the patient's overall welfare, previously expressed wishes and values, and clinical judgement, not cost considerations.$x$, 5),
('e2000000-0000-0000-0000-000000000014', 'A', '60 mg subcutaneous morphine over 24 hours', false, 'Ruled out because giving the same numerical dose subcutaneously as was given orally fails to account for the increased potency of the subcutaneous route and would risk opioid toxicity.', 1),
('e2000000-0000-0000-0000-000000000014', 'B', '90 mg subcutaneous morphine over 24 hours', false, 'Ruled out because this is higher than the oral dose and does not reflect the increased potency of subcutaneous morphine; it would markedly overdose the patient.', 2),
('e2000000-0000-0000-0000-000000000014', 'C', '120 mg subcutaneous morphine over 24 hours', false, 'Ruled out because this dose is double the oral dose and would result in significant opioid toxicity given the increased potency of the subcutaneous route.', 3),
('e2000000-0000-0000-0000-000000000014', 'D', '30 mg subcutaneous morphine over 24 hours', true, 'Correct. Subcutaneous morphine is approximately twice as potent as oral morphine, so the oral 24-hour dose is halved when converting to the subcutaneous route; 60 mg oral morphine over 24 hours converts to approximately 30 mg subcutaneous morphine over 24 hours.', 4),
('e2000000-0000-0000-0000-000000000014', 'E', '15 mg subcutaneous morphine over 24 hours', false, 'Ruled out because this underestimates the correct converted dose and risks undertreating his pain and precipitating withdrawal-type symptoms.', 5),
('e2000000-0000-0000-0000-000000000015', 'A', '120 mg subcutaneous diamorphine over 24 hours', false, 'Ruled out because this fails to apply any dose reduction for the increased potency of subcutaneous diamorphine relative to oral morphine, and would substantially overdose the patient.', 1),
('e2000000-0000-0000-0000-000000000015', 'B', '40 mg subcutaneous diamorphine over 24 hours', true, 'Correct. When converting oral morphine to subcutaneous diamorphine, the 24-hour oral morphine dose is divided by three because diamorphine is more potent than morphine on a milligram-for-milligram subcutaneous basis; 120 mg oral morphine converts to approximately 40 mg subcutaneous diamorphine over 24 hours.', 2),
('e2000000-0000-0000-0000-000000000015', 'C', '60 mg subcutaneous diamorphine over 24 hours', false, 'Ruled out because this applies the morphine-to-subcutaneous-morphine (divide by two) conversion rather than the correct oral morphine to subcutaneous diamorphine (divide by three) conversion, resulting in too high a dose.', 3),
('e2000000-0000-0000-0000-000000000015', 'D', '240 mg subcutaneous diamorphine over 24 hours', false, 'Ruled out because this doubles rather than reduces the oral dose and would cause severe opioid toxicity.', 4),
('e2000000-0000-0000-0000-000000000015', 'E', '20 mg subcutaneous diamorphine over 24 hours', false, 'Ruled out because this underestimates the converted dose, which would likely leave her pain poorly controlled and risk withdrawal-type symptoms.', 5),
('e2000000-0000-0000-0000-000000000016', 'A', 'Prescribe the same total daily dose of oxycodone as he was taking of morphine', false, 'Ruled out because oxycodone is more potent than morphine on an equivalent oral dose, so prescribing an identical dose would risk opioid toxicity.', 1),
('e2000000-0000-0000-0000-000000000016', 'B', 'Double his previous morphine dose when calculating the oxycodone dose', false, 'Ruled out because this would markedly overestimate the oxycodone requirement, as oxycodone is more, not less, potent than morphine, so doubling the numeric morphine dose would cause a significant overdose.', 2),
('e2000000-0000-0000-0000-000000000016', 'C', 'Start oxycodone at the standard opioid-naive starting dose, ignoring his established morphine requirement', false, 'Ruled out because he is already opioid-tolerant on a significant morphine dose; starting at an opioid-naive dose would likely undertreat his pain and cause a withdrawal-type deterioration.', 3),
('e2000000-0000-0000-0000-000000000016', 'D', 'Convert using the standard oral morphine to oral oxycodone potency ratio (oxycodone being roughly one and a half to two times more potent than morphine), then titrate against his response', true, 'Correct. Oral oxycodone is more potent than oral morphine on a milligram-for-milligram basis; the total 24-hour oral morphine dose should be converted using this ratio to give an approximate starting oxycodone dose, which is then titrated according to analgesic effect and side effects.', 4),
('e2000000-0000-0000-0000-000000000016', 'E', 'Avoid switching opioids altogether and instead simply add a second strong opioid alongside the morphine', false, 'Ruled out because combining two different strong opioids concurrently is not standard practice and increases risk of toxicity; opioid switching using an appropriate conversion is the recognised approach when side effects limit tolerability.', 5),
('e2000000-0000-0000-0000-000000000017', 'A', 'Increase the codeine dose further beyond the maximum recommended dose', false, 'Ruled out because weak opioids like codeine have a dose ceiling beyond which further increases provide minimal extra analgesic benefit while increasing side effects, and exceeding the maximum recommended dose is unsafe.', 1),
('e2000000-0000-0000-0000-000000000017', 'B', 'Add a second weak opioid, such as dihydrocodeine, alongside the codeine', false, 'Ruled out because combining two weak opioids does not provide additional analgesic benefit beyond their shared ceiling effect and increases the risk of side effects without improving pain control.', 2),
('e2000000-0000-0000-0000-000000000017', 'C', 'Stop the codeine and start a low-dose strong opioid such as oral morphine, titrating according to response', true, 'Correct. Codeine 60 mg four times daily is close to its maximum recommended dose, and weak opioids have a ceiling effect beyond which increasing the dose gives little additional analgesia but more side effects; the appropriate step is to move up the WHO analgesic ladder to a low-dose strong opioid.', 3),
('e2000000-0000-0000-0000-000000000017', 'D', 'Stop all opioids and rely on paracetamol alone', false, 'Ruled out because stopping opioids entirely in a patient with ongoing, poorly controlled cancer-related bone pain would leave her under-treated; the WHO ladder recommends stepping up, not down, when pain is inadequately controlled.', 4),
('e2000000-0000-0000-0000-000000000017', 'E', 'Refer for urgent radiotherapy without addressing her analgesia in the interim', false, 'Ruled out because while radiotherapy can be an effective treatment for localised bone metastases, her immediate, poorly controlled pain still requires prompt analgesic escalation while awaiting or alongside any oncological treatment.', 5),
('e2000000-0000-0000-0000-000000000018', 'A', '15 mg subcutaneously, equivalent to half the total 24-hour dose', false, 'Ruled out because this dose is far higher than the standard breakthrough calculation and would risk significant opioid toxicity if given on top of the background infusion.', 1),
('e2000000-0000-0000-0000-000000000018', 'B', 'Approximately 5 mg subcutaneously, equivalent to one-sixth of the total 24-hour dose', true, 'Correct. The standard approach to breakthrough (as required) opioid dosing is to prescribe approximately one-sixth of the total 24-hour background opioid dose, given by the same route; here one-sixth of 30 mg is approximately 5 mg.', 2),
('e2000000-0000-0000-0000-000000000018', 'C', '30 mg subcutaneously, equal to the full 24-hour background dose', false, 'Ruled out because giving a breakthrough dose equal to the entire 24-hour background dose would cause severe overdose and respiratory depression.', 3),
('e2000000-0000-0000-0000-000000000018', 'D', '1 mg subcutaneously, a fixed low dose regardless of the background infusion dose', false, $x$Ruled out because breakthrough doses should be calculated proportionally to the patient's individual background opioid dose, not fixed at an arbitrary low amount, or the breakthrough pain may remain inadequately treated.$x$, 4),
('e2000000-0000-0000-0000-000000000018', 'E', 'No breakthrough dose is needed once a syringe driver is running', false, 'Ruled out because patients on a continuous background infusion still experience episodes of breakthrough pain and require an appropriately calculated as-required dose available in addition to the infusion.', 5),
('e2000000-0000-0000-0000-000000000019', 'A', 'Morphine at the standard opioid-naive starting dose, with no adjustment for renal function', false, $x$Ruled out because morphine's active metabolites (which have analgesic and toxic effects) accumulate in renal impairment, increasing the risk of sedation and respiratory depression if renal function is not taken into account.$x$, 1),
('e2000000-0000-0000-0000-000000000019', 'B', 'Diamorphine at a higher than usual starting dose to ensure adequate analgesia', false, 'Ruled out because diamorphine is metabolised to morphine and carries the same risk of metabolite accumulation in renal impairment; a higher starting dose would increase this risk further, not mitigate it.', 2),
('e2000000-0000-0000-0000-000000000019', 'C', 'Codeine at a high dose, since weak opioids are considered safer in renal impairment', false, 'Ruled out because codeine is also metabolised to morphine and its metabolites accumulate in renal failure, and in any case a weak opioid would not be an appropriate choice for significant, opioid-requiring pain.', 3),
('e2000000-0000-0000-0000-000000000019', 'D', 'No opioid should be used at all in renal impairment; only non-opioid analgesics are safe', false, 'Ruled out because opioids can be used safely in renal impairment with appropriate choice of agent (such as oxycodone, fentanyl or alfentanil), cautious dosing and monitoring, rather than being avoided altogether.', 4),
('e2000000-0000-0000-0000-000000000019', 'E', 'Oxycodone or alfentanil, at a cautiously reduced starting dose with close monitoring', true, 'Correct. In significant renal impairment, morphine is best avoided as first choice because its active metabolites accumulate and increase the risk of toxicity; oxycodone (used cautiously) and, for parenteral use, alfentanil or fentanyl are generally preferred, started at a low dose with careful titration and monitoring.', 5),
('e2000000-0000-0000-0000-000000000020', 'A', 'Continue her previous modified-release morphine (or provide equivalent short-acting cover) for approximately 12 hours after applying the first patch, since fentanyl patches take time to reach steady-state analgesic levels', true, 'Correct. Transdermal fentanyl patches take around 12 hours to begin providing meaningful analgesia and considerably longer to reach steady state, so the previous background opioid (or equivalent short-acting cover) must be continued for approximately 12 hours after the first patch is applied to avoid a gap in analgesia.', 1),
('e2000000-0000-0000-0000-000000000020', 'B', 'Stop all other analgesia immediately when the patch is applied, as it will provide instant pain relief', false, 'Ruled out because fentanyl patches do not provide immediate analgesia; abruptly stopping background opioid cover at the moment of patch application would leave a dangerous gap in pain control.', 2),
('e2000000-0000-0000-0000-000000000020', 'C', 'Apply two patches at once for the first 24 hours to compensate for the delayed onset', false, 'Ruled out because doubling the patch dose does not address the delayed onset appropriately and instead risks a delayed toxic accumulation of fentanyl once steady state is reached.', 3),
('e2000000-0000-0000-0000-000000000020', 'D', 'Increase the oral morphine dose substantially before switching, to build up a reserve', false, $x$Ruled out because this is not how the transition is managed; the correct approach is to continue the established background opioid dose (not increase it) as cover during the patch's onset period, then convert appropriately.$x$, 4),
('e2000000-0000-0000-0000-000000000020', 'E', 'Remove the patch after four hours if pain is not immediately improved', false, 'Ruled out because fentanyl patches require substantially longer than four hours to begin providing analgesia; removing it this early would not allow it to work and would not represent a failure of the treatment.', 5),
('e2000000-0000-0000-0000-000000000021', 'A', 'Stop or substantially reduce the opioid infusion, treat the underlying dehydration, and if respiratory depression is severe give small, carefully titrated doses of naloxone rather than a standard full reversal dose', true, 'Correct. This presentation (drowsiness, pinpoint pupils, myoclonus, reduced respiratory rate) indicates opioid toxicity, likely precipitated by metabolite accumulation from acute kidney injury; the opioid should be reduced or stopped and dehydration corrected, and if naloxone is required for significant respiratory depression it should be given in small, titrated doses to reverse toxicity without precipitating severe pain or an acute withdrawal-like crisis in an opioid-tolerant patient.', 1),
('e2000000-0000-0000-0000-000000000021', 'B', 'Give a full standard reversal dose of naloxone immediately as used in acute opioid overdose in an opioid-naive patient', false, 'Ruled out because a full naloxone reversal dose in an opioid-tolerant palliative patient can precipitate severe pain, agitation and an acute withdrawal-like crisis; small, titrated doses aimed at improving respiratory drive while preserving some analgesia are preferred.', 2),
('e2000000-0000-0000-0000-000000000021', 'C', 'Increase the syringe driver rate to treat what is assumed to be undertreated pain', false, 'Ruled out because the clinical picture (myoclonus, pinpoint pupils, reduced respiratory rate, drowsiness) indicates opioid toxicity, not undertreated pain; increasing the dose would worsen toxicity.', 3),
('e2000000-0000-0000-0000-000000000021', 'D', 'Continue the same infusion rate unchanged and simply observe, as this is an expected feature of terminal decline', false, 'Ruled out because this presentation reflects a specific, partly reversible problem (opioid toxicity compounded by acute kidney injury) that should be actively managed, not assumed to be an inevitable, unmodifiable part of dying.', 4),
('e2000000-0000-0000-0000-000000000021', 'E', 'Switch immediately to an equivalent dose of oral opioid without reducing the total dose', false, 'Ruled out because switching route without addressing the underlying toxicity and reducing the dose does not resolve the problem and may simply continue the toxic exposure.', 5),
('e2000000-0000-0000-0000-000000000022', 'A', 'A broad-spectrum antibiotic only, in case of further infection', false, 'Ruled out because anticipatory end-of-life prescribing focuses on symptom control (pain, secretions, agitation, nausea), not antimicrobial cover, which is a separate clinical decision depending on goals of care.', 1),
('e2000000-0000-0000-0000-000000000022', 'B', 'A stimulant laxative alone, as constipation is the most urgent anticipated symptom', false, $x$Ruled out because while opioid-induced constipation is important to manage proactively with regular oral laxatives, the anticipatory subcutaneous 'as required' medications specifically address the four core distressing symptoms above, not laxation.$x$, 2),
('e2000000-0000-0000-0000-000000000022', 'C', 'An opioid for pain and breathlessness, an antimuscarinic (such as hyoscine butylbromide) for respiratory secretions, a sedative/anxiolytic (such as midazolam) for agitation or distress, and an antiemetic (such as levomepromazine or haloperidol) for nausea and vomiting', true, 'Correct. Standard anticipatory prescribing at the end of life covers the four most common distressing symptoms: pain/breathlessness (opioid), noisy respiratory secretions (an antimuscarinic such as hyoscine butylbromide), agitation or terminal restlessness (a sedative such as midazolam), and nausea/vomiting (an antiemetic such as levomepromazine or haloperidol), so that any of these can be treated promptly if they arise.', 3),
('e2000000-0000-0000-0000-000000000022', 'D', 'An anticoagulant, to prevent venous thromboembolism in the dying phase', false, 'Ruled out because anticoagulation is not part of standard anticipatory symptom-control prescribing at the end of life, and continuing or starting anticoagulants in the dying phase is not appropriate.', 4),
('e2000000-0000-0000-0000-000000000022', 'E', 'An oral antihypertensive, to keep blood pressure controlled', false, 'Ruled out because in a patient approaching the end of life, non-essential medications such as antihypertensives for long-term risk reduction are typically stopped rather than continued, and this is not part of anticipatory symptom-control prescribing.', 5),
('e2000000-0000-0000-0000-000000000023', 'A', 'Stop the opioid infusion completely and do not restart it', false, $x$Ruled out because a local site reaction does not mean the medication itself needs to be stopped; the driver should simply be resited so the patient's symptom control is not interrupted.$x$, 1),
('e2000000-0000-0000-0000-000000000023', 'B', 'Increase the infusion rate to compensate for reduced absorption at the inflamed site', false, 'Ruled out because the appropriate response to a site reaction is to resite the infusion, not to increase the dose, which would not address the local skin problem and could risk overdose once absorption at a fresh site is normal.', 2),
('e2000000-0000-0000-0000-000000000023', 'C', 'Switch the patient to intramuscular injections instead of a subcutaneous infusion', false, 'Ruled out because intramuscular injections are more painful and are not the standard route for continuous palliative symptom control; resiting the subcutaneous line is the appropriate first step.', 3),
('e2000000-0000-0000-0000-000000000023', 'D', 'Ignore the skin changes since they are expected to resolve on their own without any action', false, 'Ruled out because a red, swollen, itchy site can affect drug absorption and patient comfort, so it should be actively managed by resiting rather than ignored.', 4),
('e2000000-0000-0000-0000-000000000023', 'E', 'Resite the cannula to a new area and continue the infusion, monitoring the new site', true, 'Correct. A local skin reaction at a subcutaneous infusion site is a recognised, common problem and is managed by resiting the cannula to a fresh area (for example rotating around the abdomen, thighs or upper arms) rather than stopping the medication or the driver itself.', 5),
('e2000000-0000-0000-0000-000000000024', 'A', 'Continue the same background dose unchanged since breakthrough doses are working as intended', false, 'Ruled out because requiring multiple breakthrough doses in 24 hours signals inadequate background control, and the infusion dose should be increased rather than left unchanged.', 1),
('e2000000-0000-0000-0000-000000000024', 'B', 'Increase the background 24-hour infusion dose to account for the total opioid she has required (background plus breakthrough doses), and adjust the breakthrough dose accordingly', true, 'Correct. Frequent use of breakthrough doses indicates the background dose is insufficient; the total amount of opioid used in the previous 24 hours (background infusion plus breakthrough doses) should be added up and used to calculate a new, higher background infusion dose, with the breakthrough dose recalculated as a proportion of this new total.', 2),
('e2000000-0000-0000-0000-000000000024', 'C', 'Reduce the background infusion dose because she is receiving too much opioid overall', false, 'Ruled out because there is no indication of opioid toxicity here; her pattern of frequent breakthrough use indicates undertreatment, so the dose should be increased, not reduced.', 3),
('e2000000-0000-0000-0000-000000000024', 'D', 'Stop the breakthrough doses and rely on the background infusion alone', false, 'Ruled out because breakthrough analgesia remains an important safety net even after the background dose is increased, and removing it would leave episodes of pain untreated.', 4),
('e2000000-0000-0000-0000-000000000024', 'E', 'Switch her immediately to a different opioid without first considering simple dose titration of her current one', false, 'Ruled out because the standard first step when background analgesia is inadequate is to titrate the current opioid dose upward based on breakthrough use, not to switch opioids unless there is a specific reason such as toxicity or intolerance.', 5),
('e2000000-0000-0000-0000-000000000025', 'A', 'Start at a standard adult opioid-naive starting dose without any adjustment for her age or frailty', false, 'Ruled out because frail elderly patients are generally more sensitive to opioids and their side effects (such as sedation and falls risk), so extra caution and a lower starting dose is appropriate.', 1),
('e2000000-0000-0000-0000-000000000025', 'B', 'Start with a high-dose modified-release opioid preparation to achieve rapid pain control', false, 'Ruled out because starting an opioid-naive patient, particularly one who is frail and elderly, on a high-dose modified-release preparation risks significant toxicity as there is no way to titrate quickly if she is oversedated.', 2),
('e2000000-0000-0000-0000-000000000025', 'C', 'Avoid opioids altogether in patients over 85 years old regardless of their pain severity', false, 'Ruled out because age alone is not a reason to withhold appropriate analgesia; opioids can and should be used when clinically indicated, with cautious low-dose titration in frail older patients.', 3),
('e2000000-0000-0000-0000-000000000025', 'D', 'Start a low dose of immediate-release oral morphine (or equivalent), titrating the dose upward gradually according to response and tolerability, with extra caution given her age and frailty', true, $x$Correct. In an opioid-naive, frail elderly patient, opioids should be started at a low dose and titrated slowly ('start low, go slow'), reflecting increased sensitivity to opioid effects and side effects in older, frail patients, rather than starting at a standard adult dose.$x$, 4),
('e2000000-0000-0000-0000-000000000025', 'E', 'Start a transdermal fentanyl patch as the first-line strong opioid in an opioid-naive patient', false, 'Ruled out because transdermal fentanyl patches are not recommended as the first opioid in an opioid-naive patient because their long onset and offset make initial titration difficult and unsafe; a short-acting oral opioid is preferred to establish requirements first.', 5),
('e2000000-0000-0000-0000-000000000026', 'A', 'A regular antiemetic for the entire duration of opioid treatment, as nausea never improves', false, 'Ruled out because opioid-induced nausea, while common initially, typically improves with tolerance over days; unlike constipation, it does not require indefinite regular co-prescription, though short-term as-required antiemetic cover is often given.', 1),
('e2000000-0000-0000-0000-000000000026', 'B', 'A regular laxative (combining a stimulant and/or softening agent) to prevent opioid-induced constipation', true, 'Correct. Opioids almost universally cause constipation through reduced gut motility, and tolerance to this effect does not develop over time (unlike nausea and sedation); a regular prophylactic laxative should be co-prescribed with any regular opioid unless there is a specific contraindication such as bowel obstruction.', 2),
('e2000000-0000-0000-0000-000000000026', 'C', 'A bulk-forming laxative such as ispaghula husk as the laxative of choice', false, 'Ruled out because bulk-forming laxatives require adequate fluid intake and are generally avoided in opioid-induced constipation, as they can worsen symptoms in patients with reduced mobility or fluid intake; stimulant and/or softening laxatives are preferred.', 3),
('e2000000-0000-0000-0000-000000000026', 'D', 'No additional prophylactic medication is required with opioids', false, 'Ruled out because opioid-induced constipation is near-universal and does not resolve with tolerance, so a prophylactic laxative should be routinely co-prescribed.', 4),
('e2000000-0000-0000-0000-000000000026', 'E', 'A proton pump inhibitor to prevent opioid-related gastric ulceration', false, 'Ruled out because opioids are not typically associated with gastric ulceration in the way NSAIDs are, so routine proton pump inhibitor co-prescription is not the standard practice specifically for opioid initiation.', 5),
('e2000000-0000-0000-0000-000000000027', 'A', 'Add a weak opioid (such as codeine) or, alternatively, a low dose of a strong opioid, alongside continuing paracetamol', true, 'Correct. When pain is not controlled on a non-opioid analgesic alone, the WHO analgesic ladder recommends stepping up to add a weak opioid (or, in current practice, sometimes moving directly to a low-dose strong opioid), while continuing the non-opioid base analgesic and considering adjuvants such as an NSAID if not contraindicated.', 1),
('e2000000-0000-0000-0000-000000000027', 'B', 'Increase the paracetamol dose beyond the maximum recommended daily dose', false, 'Ruled out because exceeding the maximum recommended paracetamol dose risks hepatotoxicity without providing additional analgesic benefit; the ladder recommends adding a different class of analgesic, not exceeding the safe maximum of the current one.', 2),
('e2000000-0000-0000-0000-000000000027', 'C', 'Stop paracetamol and start a strong opioid alone without any non-opioid analgesic', false, 'Ruled out because non-opioid analgesics such as paracetamol are typically continued alongside opioids as part of a multimodal approach, rather than stopped when moving up the ladder.', 3),
('e2000000-0000-0000-0000-000000000027', 'D', 'Refer for immediate palliative sedation', false, 'Ruled out because this is inappropriate and disproportionate for ongoing but not severely refractory bone pain; standard stepwise analgesic escalation should be tried first.', 4),
('e2000000-0000-0000-0000-000000000027', 'E', 'Advise him to simply tolerate the pain since bone metastases are not treatable', false, 'Ruled out because bone pain from metastases is very much treatable with appropriate analgesic escalation, and adjuvant treatments such as radiotherapy or bisphosphonates, and should not be dismissed as untreatable.', 5),
('e2000000-0000-0000-0000-000000000028', 'A', 'High-dose ibuprofen as first-line treatment', false, 'Ruled out because NSAIDs are not first-line treatment for neuropathic pain, which has a different underlying mechanism to nociceptive/inflammatory pain and responds poorly to NSAIDs alone.', 1),
('e2000000-0000-0000-0000-000000000028', 'B', 'Strong opioids as the first choice before trying any neuropathic agent', false, 'Ruled out because strong opioids are not first-line for neuropathic pain and are generally reserved for cases where first-line neuropathic agents have failed, given their comparatively limited efficacy and higher side-effect burden for this indication.', 2),
('e2000000-0000-0000-0000-000000000028', 'C', 'Reassurance only, as neuropathic pain cannot be treated pharmacologically', false, 'Ruled out because effective pharmacological options exist for neuropathic pain, and it should not be dismissed as untreatable.', 3),
('e2000000-0000-0000-0000-000000000028', 'D', 'Topical corticosteroid cream applied to the feet', false, 'Ruled out because topical corticosteroids have no established role in the treatment of neuropathic pain such as diabetic peripheral neuropathy.', 4),
('e2000000-0000-0000-0000-000000000028', 'E', 'A trial of amitriptyline, gabapentin, pregabalin or duloxetine, started at a low dose and titrated according to response', true, 'Correct. Neuropathic pain, such as painful diabetic peripheral neuropathy, is characteristically poorly responsive to standard opioid or non-opioid analgesics alone and responds better to specific neuropathic agents including amitriptyline, gabapentin, pregabalin or duloxetine, any of which may be tried first-line, starting low and titrating up.', 5),
('e2000000-0000-0000-0000-000000000029', 'A', 'Avoid NSAIDs and radiotherapy entirely and rely on opioids alone', false, 'Ruled out because NSAIDs and localised radiotherapy have specific, evidence-based roles in managing bone metastasis pain and should be actively considered as part of a multimodal approach, not excluded when there is no contraindication.', 1),
('e2000000-0000-0000-0000-000000000029', 'B', 'Increase her opioid dose repeatedly without considering adjuvant treatments', false, 'Ruled out because relying solely on escalating opioid doses ignores adjuvant treatments (NSAIDs, radiotherapy, bisphosphonates) that can be particularly effective for bone pain and may allow better control with a lower opioid burden.', 2),
('e2000000-0000-0000-0000-000000000029', 'C', 'Recommend bed rest as the primary treatment for her pain', false, 'Ruled out because bed rest alone does not address the underlying cause of bone pain and can lead to complications such as deconditioning, venous thromboembolism and pressure injury without providing effective analgesia.', 3),
('e2000000-0000-0000-0000-000000000029', 'D', 'A trial of a regular NSAID as an adjuvant analgesic, alongside considering referral for localised palliative radiotherapy', true, 'Correct. NSAIDs are particularly effective adjuvant analgesics for bone pain due to their anti-inflammatory action at sites of bony metastatic disease, and localised palliative radiotherapy is an effective, specific treatment for pain from a discrete area of bone metastasis, both of which should be considered alongside systemic opioid analgesia.', 4),
('e2000000-0000-0000-0000-000000000029', 'E', 'Refer for surgical fixation of all affected bones regardless of fracture risk', false, 'Ruled out because surgical fixation is reserved for bones at significant risk of pathological fracture or already fractured, not as a routine treatment for bone pain in the absence of such risk.', 5),
('e2000000-0000-0000-0000-000000000030', 'A', 'A low starting dose of a strong opioid, titrated with caution', false, 'Ruled out because opioids, used cautiously and appropriately dose-adjusted for renal function, remain an appropriate option for escalating cancer pain in this patient, unlike NSAIDs which carry specific contraindications here.', 1),
('e2000000-0000-0000-0000-000000000030', 'B', 'Paracetamol, continued alongside other analgesics', false, 'Ruled out because paracetamol is not contraindicated by renal impairment or peptic ulcer history and can safely continue as part of a multimodal analgesic regimen.', 2),
('e2000000-0000-0000-0000-000000000030', 'C', 'A non-steroidal anti-inflammatory drug (NSAID) such as ibuprofen or naproxen', true, 'Correct. NSAIDs should be avoided in this patient because of the combination of significant renal impairment (risk of further nephrotoxicity) and a history of gastrointestinal bleeding (risk of recurrent peptic ulceration and bleeding), both recognised contraindications or major cautions for NSAID use.', 3),
('e2000000-0000-0000-0000-000000000030', 'D', 'A trial of a neuropathic agent if there is a neuropathic component to his pain', false, 'Ruled out because neuropathic agents are not contraindicated by his renal impairment or ulcer history (though doses of some may need adjustment for renal function) and may be appropriate if neuropathic pain is present.', 4),
('e2000000-0000-0000-0000-000000000030', 'E', 'Referral for localised palliative radiotherapy to painful bone metastases', false, 'Ruled out because radiotherapy is not contraindicated by his renal or gastrointestinal history and remains an appropriate option for localised bone pain.', 5),
('e2000000-0000-0000-0000-000000000031', 'A', 'Simply continuing to increase her opioid dose until the pain fully resolves', false, 'Ruled out because her pain has a significant psychosocial and existential component that will not be fully addressed by opioid dose escalation alone, and further increasing opioids without addressing these factors risks toxicity without proportionate benefit.', 1),
('e2000000-0000-0000-0000-000000000031', 'B', 'Concluding that she is exaggerating her pain for attention', false, 'Ruled out because this dismisses genuine, multifactorial suffering and is not an appropriate or respectful clinical interpretation of her presentation.', 2),
('e2000000-0000-0000-0000-000000000031', 'C', 'Assuming her pain must be entirely due to an undiagnosed new physical cause requiring further invasive investigation', false, 'Ruled out because while new physical causes should always be considered and excluded where clinically indicated, the description given strongly suggests significant psychosocial and existential contributors, which invasive investigation alone would not address.', 3),
('e2000000-0000-0000-0000-000000000031', 'D', 'Referring her only for physiotherapy, as this is the definitive treatment for total pain', false, 'Ruled out because physiotherapy alone does not address the psychological, social and spiritual dimensions described here; a broader multidisciplinary approach is needed.', 4),
('e2000000-0000-0000-0000-000000000031', 'E', $x$The concept of 'total pain', recognising that physical, psychological, social and spiritual factors all contribute to her overall experience of pain, requiring a holistic multidisciplinary approach$x$, true, $x$Correct. 'Total pain' describes how psychological distress, social concerns (such as worry about her children), and spiritual or existential concerns can all amplify the perceived severity of physical pain; addressing pain effectively in such cases requires a holistic assessment and multidisciplinary support (for example psychology, social work, chaplaincy), not analgesic escalation alone.$x$, 5),
('e2000000-0000-0000-0000-000000000032', 'A', 'Give an appropriate breakthrough dose of a fast-acting opioid shortly before the anticipated painful procedure (such as turning or dressing changes)', true, 'Correct. This pattern describes incident (movement- or procedure-related) pain, which is best managed by pre-emptively giving a fast-acting breakthrough opioid dose shortly before the anticipated trigger, so that peak analgesic effect coincides with the painful procedure.', 1),
('e2000000-0000-0000-0000-000000000032', 'B', 'Increase his regular background opioid dose substantially to try to prevent any incident pain', false, 'Ruled out because increasing the background dose to cover brief, predictable incident pain episodes risks oversedation and toxicity between episodes, when his baseline pain is otherwise well controlled.', 2),
('e2000000-0000-0000-0000-000000000032', 'C', 'Avoid turning him or changing his dressings to prevent triggering pain', false, 'Ruled out because avoiding necessary care (turning to prevent pressure injury, dressing changes for wound care) creates other significant harms; the correct approach is to provide adequate analgesic cover for the procedure, not to avoid essential care.', 3),
('e2000000-0000-0000-0000-000000000032', 'D', 'Reassure him that this brief pain is not clinically significant and does not need treatment', false, 'Ruled out because recurrent, severe procedure-related pain is a recognised and treatable problem (incident pain) and dismissing it leaves him suffering unnecessarily during routine care.', 4),
('e2000000-0000-0000-0000-000000000032', 'E', 'Switch him to a different opioid entirely, as this pattern indicates his current opioid is not working', false, 'Ruled out because his baseline pain control is good; the issue is specifically incident pain related to movement/procedures, which is addressed with pre-emptive breakthrough dosing rather than a full opioid switch.', 5),
('e2000000-0000-0000-0000-000000000033', 'A', 'Reassure him that back pain is common in advanced cancer and arrange routine outpatient review', false, 'Ruled out because this presentation has red flag features strongly suggestive of spinal cord compression, a medical emergency requiring same-day urgent assessment and imaging, not a routine outpatient review.', 1),
('e2000000-0000-0000-0000-000000000033', 'B', 'Prescribe simple analgesia and discharge home with safety-netting advice', false, 'Ruled out because discharging a patient with suspected cord compression risks irreversible paralysis if the diagnosis is missed; this requires urgent same-day inpatient assessment, imaging and treatment.', 2),
('e2000000-0000-0000-0000-000000000033', 'C', 'Arrange urgent whole-spine MRI, start high-dose dexamethasone, and make an urgent referral to the acute oncology or spinal service, as this presentation is highly suspicious for metastatic spinal cord compression', true, 'Correct. Progressive, severe back pain (particularly worse at night), new gait disturbance, a sensory band, and upper motor neuron signs in a patient with known spinal metastases are red flag features of metastatic spinal cord compression, a time-critical oncological emergency requiring urgent MRI imaging, immediate high-dose corticosteroids, and urgent specialist referral to preserve neurological function.', 3),
('e2000000-0000-0000-0000-000000000033', 'D', 'Arrange physiotherapy for gait rehabilitation before any further investigation', false, 'Ruled out because physiotherapy does not address the underlying suspected cord compression, and delaying urgent imaging and steroid treatment risks permanent neurological damage.', 4),
('e2000000-0000-0000-0000-000000000033', 'E', 'Wait for outpatient MRI in the next few weeks since his cancer is already known to be metastatic', false, 'Ruled out because suspected cord compression requires imaging within hours, not weeks; delay significantly increases the risk of irreversible paraplegia.', 5),
('e2000000-0000-0000-0000-000000000034', 'A', 'A stimulant laxative such as senna to relieve the colic', false, 'Ruled out because stimulant laxatives increase peristalsis and would worsen colicky pain and vomiting in the context of bowel obstruction.', 1),
('e2000000-0000-0000-0000-000000000034', 'B', 'An antispasmodic such as hyoscine butylbromide, alongside an opioid for background pain, avoiding prokinetic agents', true, 'Correct. Colicky, cramping visceral pain from bowel obstruction is typically treated with an antimuscarinic antispasmodic such as hyoscine butylbromide to reduce smooth muscle spasm, in addition to an opioid for background pain; prokinetic agents (which increase gut motility) should be avoided as they can worsen colic and vomiting in a mechanical or subacute obstruction.', 2),
('e2000000-0000-0000-0000-000000000034', 'C', 'A prokinetic agent such as metoclopramide to relieve the colicky pain', false, 'Ruled out because prokinetic agents increase gastrointestinal motility, which can worsen colic and risk perforation in the context of mechanical or subacute bowel obstruction, and are generally avoided in this setting.', 3),
('e2000000-0000-0000-0000-000000000034', 'D', 'High-dose NSAID as the primary analgesic for the colic', false, 'Ruled out because NSAIDs are not the primary treatment for visceral colic from bowel obstruction, and their gastrointestinal and renal side effects make them a less suitable choice in this context.', 4),
('e2000000-0000-0000-0000-000000000034', 'E', 'Reassurance only, without any specific pharmacological treatment for the pain', false, 'Ruled out because effective pharmacological options exist for colicky pain in malignant bowel obstruction (antispasmodics and opioids) and should be actively used rather than withheld.', 5),
('e2000000-0000-0000-0000-000000000035', 'A', 'A muscle relaxant such as baclofen', false, 'Ruled out because liver capsule pain is not due to skeletal muscle spasm, and muscle relaxants have no established role in this specific pain mechanism.', 1),
('e2000000-0000-0000-0000-000000000035', 'B', 'An antimuscarinic antispasmodic such as hyoscine butylbromide', false, 'Ruled out because antispasmodics target smooth muscle colic (for example bowel colic), not the capsular stretch pain associated with hepatomegaly.', 2),
('e2000000-0000-0000-0000-000000000035', 'C', 'A bisphosphonate such as zoledronic acid', false, 'Ruled out because bisphosphonates are used for bone pain related to skeletal metastases and hypercalcaemia, not specifically for liver capsule pain from hepatic metastases.', 3),
('e2000000-0000-0000-0000-000000000035', 'D', 'A trial of a corticosteroid such as dexamethasone, in addition to her regular analgesia', true, 'Correct. Pain from stretching of the liver capsule due to hepatic metastases (liver capsule pain) often responds well to corticosteroids, which reduce peritumoural oedema and inflammation around the liver capsule, and are commonly used as an adjuvant alongside standard analgesia for this specific pain pattern.', 4),
('e2000000-0000-0000-0000-000000000035', 'E', 'A high-dose stimulant laxative', false, 'Ruled out because laxatives have no role in treating pain from liver capsule stretch; this is not related to bowel motility.', 5),
('e2000000-0000-0000-0000-000000000036', 'A', 'Paracetamol at standard maximum doses with no caution required', false, 'Ruled out because although paracetamol can often still be used in liver disease, caution and often dose reduction is needed in significant hepatic impairment because of the risk of hepatotoxicity, so it is not free of caution.', 1),
('e2000000-0000-0000-0000-000000000036', 'B', 'NSAIDs as the preferred first-line analgesic given his pain', false, 'Ruled out because NSAIDs are particularly hazardous in liver failure with coagulopathy and ascites, given increased bleeding risk and risk of precipitating renal impairment (hepatorenal syndrome); they should be avoided.', 2),
('e2000000-0000-0000-0000-000000000036', 'C', 'Codeine and standard doses of morphine, both of which should be used cautiously at reduced doses and with extended dosing intervals due to impaired hepatic metabolism and increased sensitivity to sedation', true, 'Correct. In significant liver failure, opioids that rely on hepatic metabolism (including codeine, which requires hepatic conversion to its active form, and morphine) can accumulate and have prolonged and unpredictable effects; doses should be reduced, dosing intervals extended, and patients monitored closely for sedation and encephalopathy, alongside avoiding NSAIDs given the coagulopathy and renal risk.', 3),
('e2000000-0000-0000-0000-000000000036', 'D', 'Any opioid can be used at full standard doses without adjustment since pain must be controlled', false, 'Ruled out because opioids metabolised by the liver can accumulate unpredictably in hepatic failure, risking sedation, respiratory depression and encephalopathy if used at full unadjusted doses.', 4),
('e2000000-0000-0000-0000-000000000036', 'E', 'Aspirin as the analgesic of choice for his pain', false, 'Ruled out because aspirin carries a significant bleeding risk in a patient who is already coagulopathic, making it an inappropriate choice.', 5),
('e2000000-0000-0000-0000-000000000037', 'A', 'Carbamazepine, titrated according to response and tolerability', true, 'Correct. This history of brief, severe, stabbing unilateral facial pain triggered by light touch or chewing is characteristic of trigeminal neuralgia, for which carbamazepine is the established first-line pharmacological treatment.', 1),
('e2000000-0000-0000-0000-000000000037', 'B', 'A strong opioid such as morphine', false, 'Ruled out because opioids are not effective first-line treatment for trigeminal neuralgia, which responds better to specific anticonvulsant agents such as carbamazepine.', 2),
('e2000000-0000-0000-0000-000000000037', 'C', 'A short course of oral antibiotics', false, 'Ruled out because there is no indication of an infective cause here, and this presentation is classic for a specific neuropathic facial pain syndrome, not an infection.', 3),
('e2000000-0000-0000-0000-000000000037', 'D', 'A topical NSAID gel applied to the face', false, 'Ruled out because topical NSAIDs have no established role in the treatment of trigeminal neuralgia.', 4),
('e2000000-0000-0000-0000-000000000037', 'E', 'Reassurance and no treatment, as the episodes are brief', false, 'Ruled out because although individual episodes are brief, trigeminal neuralgia causes recurrent, severe, disabling pain and effective pharmacological treatment (carbamazepine) is available and should be offered.', 5),
('e2000000-0000-0000-0000-000000000038', 'A', 'Manage with analgesia and advice to continue normal weight-bearing activity', false, 'Ruled out because continuing normal weight-bearing in a bone with a high fracture risk significantly increases the chance of an acute pathological fracture, which carries much higher morbidity than proactive prophylactic management.', 1),
('e2000000-0000-0000-0000-000000000038', 'B', 'Arrange radiotherapy alone with no orthopaedic input, regardless of fracture risk', false, 'Ruled out because radiotherapy can help with pain and local tumour control but does not immediately strengthen bone at high risk of imminent fracture; orthopaedic assessment for prophylactic fixation is needed first when fracture risk is high, often followed by radiotherapy afterwards.', 2),
('e2000000-0000-0000-0000-000000000038', 'C', 'Advise strict bed rest indefinitely as the definitive management', false, 'Ruled out because indefinite bed rest is not a definitive treatment for impending pathological fracture and carries its own risks (venous thromboembolism, deconditioning, pressure injury); definitive assessment for fixation is required.', 3),
('e2000000-0000-0000-0000-000000000038', 'D', 'Reassure him that pain alone does not indicate any risk of fracture', false, 'Ruled out because increasing pain on weight-bearing combined with significant cortical destruction on imaging are recognised markers of impending pathological fracture, and should prompt urgent action, not reassurance.', 4),
('e2000000-0000-0000-0000-000000000038', 'E', 'Urgent referral to orthopaedics for consideration of prophylactic surgical fixation, given the significant risk of impending pathological fracture', true, 'Correct. A lytic metastasis causing substantial cortical destruction (involving more than half the bone diameter) with increasing pain on weight-bearing indicates a high risk of impending pathological fracture; urgent orthopaedic referral for consideration of prophylactic fixation is appropriate, as this can prevent a fracture and its associated complications, and generally provides better function than fixation after fracture has occurred.', 5),
('e2000000-0000-0000-0000-000000000039', 'A', 'Stop the morphine immediately and do not restart any opioid', false, 'Ruled out because opioid-induced nausea is usually a manageable, transient side effect that responds to antiemetics, and stopping an effective analgesic entirely is not the first step when a simple, effective treatment is available.', 1),
('e2000000-0000-0000-0000-000000000039', 'B', 'Reassure him that nothing can be done and he must tolerate the nausea', false, 'Ruled out because opioid-induced nausea can be effectively treated with antiemetics; telling the patient nothing can be done is inaccurate and leaves him with unnecessary distress.', 2),
('e2000000-0000-0000-0000-000000000039', 'C', 'Start a bulk-forming laxative to treat the nausea', false, 'Ruled out because laxatives treat constipation, not nausea, and a bulk-forming laxative has no role in treating opioid-induced nausea specifically.', 3),
('e2000000-0000-0000-0000-000000000039', 'D', 'Start a regular antiemetic acting on the chemoreceptor trigger zone, such as haloperidol or metoclopramide, and explain that opioid-induced nausea often improves within days as tolerance develops', true, 'Correct. Nausea occurring around the time of opioid initiation is a recognised, common side effect mediated via the chemoreceptor trigger zone; an antiemetic such as low-dose haloperidol or metoclopramide is appropriate first-line treatment, and patients should be reassured that this typically improves within days to a couple of weeks as tolerance develops, unlike constipation.', 4),
('e2000000-0000-0000-0000-000000000039', 'E', 'Arrange urgent CT imaging of the abdomen before starting any symptomatic treatment', false, 'Ruled out because this presentation (new nausea coinciding with opioid initiation, no other red flag features) is characteristic of a recognised, common opioid side effect and does not require urgent imaging before a trial of standard antiemetic treatment.', 5),
('e2000000-0000-0000-0000-000000000040', 'A', 'Cyclizine, an antihistamine antiemetic, as first-line treatment', false, 'Ruled out because cyclizine has no prokinetic action and, by having anticholinergic properties, may actually worsen gastric stasis; it is not the preferred choice for this presentation.', 1),
('e2000000-0000-0000-0000-000000000040', 'B', 'Metoclopramide, a prokinetic antiemetic, as first-line treatment', true, 'Correct. Her symptoms (early satiety, bloating, small-volume vomiting after eating, succussion splash) are characteristic of gastric stasis, often due to tumour infiltration or compression; a prokinetic antiemetic such as metoclopramide, which promotes gastric emptying, is the appropriate first-line treatment.', 2),
('e2000000-0000-0000-0000-000000000040', 'C', 'Hyoscine butylbromide as first-line treatment', false, 'Ruled out because hyoscine butylbromide is an antispasmodic used for colic and secretions, and its antimuscarinic action would tend to reduce gut motility, worsening gastric stasis rather than helping it.', 3),
('e2000000-0000-0000-0000-000000000040', 'D', 'A stimulant laxative as first-line treatment', false, 'Ruled out because a laxative treats constipation and does not address the mechanism of gastric stasis causing her nausea and vomiting.', 4),
('e2000000-0000-0000-0000-000000000040', 'E', 'No treatment is needed as these symptoms will resolve spontaneously', false, 'Ruled out because gastric stasis due to tumour infiltration is unlikely to resolve spontaneously and causes significant symptom burden; a prokinetic antiemetic provides effective symptomatic relief.', 5),
('e2000000-0000-0000-0000-000000000041', 'A', 'Metoclopramide as the first-line antiemetic to promote gastric emptying', false, 'Ruled out because metoclopramide is a prokinetic and is contraindicated in complete mechanical bowel obstruction, where increasing peristalsis against the obstruction can worsen pain and risk of perforation.', 1),
('e2000000-0000-0000-0000-000000000041', 'B', 'Domperidone at a high dose to relieve nausea', false, 'Ruled out because domperidone is also a prokinetic agent and shares the same concerns as metoclopramide in mechanical bowel obstruction.', 2),
('e2000000-0000-0000-0000-000000000041', 'C', 'A bulk-forming laxative alongside antiemetics', false, 'Ruled out because laxatives, particularly bulk-forming agents, are inappropriate and potentially harmful in complete bowel obstruction, where nothing can pass through the obstructed segment.', 3),
('e2000000-0000-0000-0000-000000000041', 'D', 'Cyclizine or, if this is insufficient, an antimuscarinic/somatostatin-analogue based approach, while avoiding prokinetic agents such as metoclopramide', true, 'Correct. In complete mechanical bowel obstruction, prokinetic antiemetics such as metoclopramide should be avoided because increasing gut motility against a mechanical obstruction can worsen colicky pain and risk perforation; non-prokinetic options such as cyclizine, along with antisecretory agents (hyoscine butylbromide, and octreotide if needed) to reduce volume and colic, are preferred.', 4),
('e2000000-0000-0000-0000-000000000041', 'E', 'No antiemetic treatment, relying on nasogastric drainage alone', false, 'Ruled out because pharmacological symptom control (antiemetics, antispasmodics, antisecretory agents) has an important role in malignant bowel obstruction alongside decisions about nasogastric drainage, and is not excluded by it.', 5),
('e2000000-0000-0000-0000-000000000042', 'A', 'Perform vigorous oropharyngeal suctioning as the first-line treatment', false, 'Ruled out because vigorous suctioning is often distressing, may not reach the source of secretions (which are often lower in the airway), and is not first-line; repositioning and antisecretory medication are preferred initial measures.', 1),
('e2000000-0000-0000-0000-000000000042', 'B', 'Reposition him (for example on his side) and give an antimuscarinic drug such as hyoscine butylbromide subcutaneously to reduce further secretions, while reassuring the family that he does not appear distressed by the noise', true, $x$Correct. 'Death rattle' from retained upper airway secretions is common in the dying phase; repositioning can help reduce the noise, and antimuscarinic drugs such as hyoscine butylbromide reduce further secretion production (though they do not clear secretions already present); importantly, the noise is usually far more distressing to family and staff than to the unconscious patient, and this should be explained sensitively.$x$, 2),
('e2000000-0000-0000-0000-000000000042', 'C', 'Give intravenous fluids to loosen the secretions so they can be coughed up', false, 'Ruled out because increasing fluids would likely increase secretion volume, and an unconscious dying patient is not able to cough effectively; this is not the appropriate management.', 3),
('e2000000-0000-0000-0000-000000000042', 'D', 'Tell the family nothing can be done and to expect the noise to worsen indefinitely with no possible intervention', false, 'Ruled out because simple, effective measures (repositioning, antimuscarinic medication) can help, and sensitive explanation to the family is an important part of managing this symptom, rather than offering no information or options.', 4),
('e2000000-0000-0000-0000-000000000042', 'E', 'Increase the opioid infusion rate specifically to treat the noisy breathing', false, 'Ruled out because opioids do not specifically treat retained secretions causing death rattle; the appropriate specific treatment is an antimuscarinic drug and repositioning, with opioid dose changes guided by evidence of pain or breathlessness, not the rattle itself.', 5),
('e2000000-0000-0000-0000-000000000043', 'A', 'High-flow oxygen regardless of his oxygen saturation, as this will definitely relieve his breathlessness', false, 'Ruled out because oxygen therapy is most beneficial when there is hypoxaemia; in a patient with only mildly reduced saturations, symptomatic breathlessness may not improve significantly with supplemental oxygen and other measures may be more effective.', 1),
('e2000000-0000-0000-0000-000000000043', 'B', 'Reassurance only, with no pharmacological treatment for the breathlessness or associated anxiety', false, 'Ruled out because effective options exist for symptomatic management of breathlessness (low-dose opioids, fan therapy, anxiolytics for the anxiety component) and these should be actively offered.', 2),
('e2000000-0000-0000-0000-000000000043', 'C', 'A low dose of an oral opioid to reduce the sensation of breathlessness, a fan directed at his face, and a low dose of a benzodiazepine or other anxiolytic to address the associated anxiety component', true, 'Correct. Low-dose opioids reduce the subjective sensation of breathlessness in advanced disease, a fan blowing air across the face can provide symptomatic relief by stimulating facial trigeminal receptors, and given the clear anxiety component worsening his breathlessness, a low-dose benzodiazepine or other anxiolytic can help break the breathlessness-anxiety cycle, alongside addressing any reversible underlying causes such as further pleural fluid drainage.', 3),
('e2000000-0000-0000-0000-000000000043', 'D', 'A short-acting bronchodilator alone, as this is the definitive treatment for cancer-related breathlessness', false, 'Ruled out because bronchodilators are useful when there is a reversible airway component (such as coexisting airway obstruction), but are not the definitive treatment for breathlessness due to pleural effusion and anxiety in this context; a broader symptomatic approach is needed.', 4),
('e2000000-0000-0000-0000-000000000043', 'E', 'A high dose of a sedating antipsychotic to control his breathlessness', false, 'Ruled out because this is not a standard or first-line approach to breathlessness management and risks significant sedation without proven benefit for this symptom specifically.', 5),
('e2000000-0000-0000-0000-000000000044', 'A', 'A combination of antiemetics, an antispasmodic, and consideration of dexamethasone and/or a somatostatin analogue such as octreotide to reduce gastrointestinal secretions, aiming to manage symptoms without a nasogastric tube where possible', true, 'Correct. Conservative (non-surgical) management of inoperable malignant bowel obstruction focuses on pharmacological symptom control: antiemetics (avoiding prokinetics), an antispasmodic for colic, and reduction of gastrointestinal secretions using corticosteroids and/or a somatostatin analogue such as octreotide, which can reduce the volume of vomiting and may allow many patients to avoid a nasogastric tube.', 1),
('e2000000-0000-0000-0000-000000000044', 'B', $x$Immediate surgery regardless of the surgical team's assessment that it is not appropriate$x$, false, 'Ruled out because the surgical team has already assessed that surgery is not appropriate given diffuse peritoneal disease; proceeding against this assessment is not appropriate and conservative management is indicated instead.', 2),
('e2000000-0000-0000-0000-000000000044', 'C', 'Insist on a nasogastric tube regardless of her preference, as it is the only possible treatment', false, 'Ruled out because pharmacological measures (antisecretory agents, antiemetics, antispasmodics) can often adequately control symptoms and reduce the need for a nasogastric tube; her preference to avoid one where possible should be respected within a conservative approach.', 3),
('e2000000-0000-0000-0000-000000000044', 'D', 'Encourage a high-fibre diet to help her bowels move despite the obstruction', false, 'Ruled out because a high-fibre diet would be inappropriate and potentially harmful in complete bowel obstruction, where oral intake often needs to be limited to what is comfortable rather than increased in fibre content.', 4),
('e2000000-0000-0000-0000-000000000044', 'E', 'Withhold all symptomatic treatment until a further surgical opinion is obtained', false, 'Ruled out because effective symptomatic treatment should be started promptly for her comfort, and should not be delayed pending a further surgical opinion when the initial assessment has already concluded surgery is not appropriate.', 5),
('e2000000-0000-0000-0000-000000000045', 'A', 'Wait until he reports constipation before starting any laxative', false, 'Ruled out because opioid-induced constipation is near-universal and predictable; proactive prophylactic laxative prescribing is preferred over a reactive approach that allows the patient to become symptomatic first.', 1),
('e2000000-0000-0000-0000-000000000045', 'B', 'Advise increased dietary fibre alone, without any laxative medication', false, 'Ruled out because dietary fibre alone is often insufficient to counteract opioid-induced reduction in gut motility, and can even worsen symptoms if fluid intake is inadequate; a stimulant/softening laxative is the standard proactive approach.', 2),
('e2000000-0000-0000-0000-000000000045', 'C', 'Prescribe a bulk-forming laxative such as ispaghula husk as the laxative of choice', false, 'Ruled out because bulk-forming laxatives are generally avoided for opioid-induced constipation, particularly if fluid intake or mobility is reduced, as they can worsen symptoms; stimulant and/or softening laxatives are preferred.', 3),
('e2000000-0000-0000-0000-000000000045', 'D', 'Reassure him that laxatives are not needed since he currently has no bowel problems', false, 'Ruled out because starting a regular opioid is itself a strong predictor of future constipation, and prophylactic laxative treatment should begin now, rather than only after problems develop.', 4),
('e2000000-0000-0000-0000-000000000045', 'E', 'Co-prescribe a regular prophylactic laxative (typically a stimulant with or without a softening agent) from the time opioid treatment starts', true, 'Correct. Opioid-induced constipation is extremely common and does not resolve with tolerance over time, so a regular prophylactic laxative should be started proactively alongside the opioid, rather than waiting for constipation to develop.', 5),
('e2000000-0000-0000-0000-000000000046', 'A', 'Give a large dose of subcutaneous midazolam immediately without any further assessment', false, 'Ruled out because sedating the patient without first considering reversible causes of her agitation risks masking a treatable problem (such as urinary retention or uncontrolled pain) rather than resolving it.', 1),
('e2000000-0000-0000-0000-000000000046', 'B', 'Physically restrain her until she settles', false, 'Ruled out because physical restraint is not an appropriate or first-line management of agitation and can worsen distress; assessment for underlying causes and appropriate pharmacological or non-pharmacological measures are preferred.', 2),
('e2000000-0000-0000-0000-000000000046', 'C', 'Assume this is simply an inevitable part of her dementia and provide no specific assessment or treatment', false, 'Ruled out because acute agitation, especially with a sudden onset, should prompt assessment for a new, potentially reversible precipitant rather than being attributed automatically to her underlying dementia without further evaluation.', 3),
('e2000000-0000-0000-0000-000000000046', 'D', 'Increase her regular background opioid dose as the first response to agitation', false, 'Ruled out because increasing opioids without first assessing whether pain, or another specific cause, is actually driving the agitation risks opioid toxicity without addressing the true underlying problem.', 4),
('e2000000-0000-0000-0000-000000000046', 'E', 'Assess for and address any reversible causes of agitation, such as urinary retention, faecal impaction, uncontrolled pain, hypoxia, or medication effects, before or alongside considering sedative treatment', true, 'Correct. Agitation and restlessness at the end of life or in delirium often has an identifiable, sometimes reversible cause (urinary retention, constipation/impaction, uncontrolled pain, hypoxia, drug toxicity, or infection); a focused assessment for these should be undertaken before or alongside sedative treatment, since sedation alone does not address an underlying treatable problem and may mask it.', 5),
('e2000000-0000-0000-0000-000000000047', 'A', 'A trial of spironolactone, and consideration of therapeutic paracentesis (ascitic drainage) if symptoms are significant or diuretics are ineffective', true, 'Correct. Malignant ascites causing troublesome symptoms is commonly managed with a trial of a diuretic such as spironolactone (which may help particularly if there is a component of portal hypertension), alongside considering therapeutic paracentesis to directly relieve pressure symptoms such as distension, discomfort and early satiety when they are significant or diuretics alone are insufficient.', 1),
('e2000000-0000-0000-0000-000000000047', 'B', 'Fluid restriction alone as the primary treatment', false, 'Ruled out because fluid restriction is not the primary or standard approach to symptomatic malignant ascites; diuretic trial and/or paracentesis are the recognised management strategies.', 2),
('e2000000-0000-0000-0000-000000000047', 'C', 'Immediate surgical peritoneal stripping regardless of symptom severity', false, 'Ruled out because surgical peritoneal stripping is not a standard or appropriate treatment for symptomatic malignant ascites; drainage and diuretics are the standard approach.', 3),
('e2000000-0000-0000-0000-000000000047', 'D', 'Broad-spectrum antibiotics as first-line treatment', false, 'Ruled out because there is no evidence of infection here, and antibiotics do not treat malignant ascites itself; they would only be indicated if there were signs of infected ascitic fluid.', 4),
('e2000000-0000-0000-0000-000000000047', 'E', 'No treatment, as malignant ascites cannot be managed symptomatically', false, 'Ruled out because malignant ascites can be effectively managed symptomatically with diuretics and/or paracentesis, and should not be dismissed as untreatable.', 5),
('e2000000-0000-0000-0000-000000000048', 'A', 'A sedating oral antihistamine as the definitive and most effective treatment', false, 'Ruled out because cholestatic pruritus is not primarily histamine-mediated, and antihistamines are generally of limited benefit for this specific type of itch, although they may provide some symptomatic sedation-related relief at night; they are not the definitive treatment.', 1),
('e2000000-0000-0000-0000-000000000048', 'B', 'Consider biliary drainage (such as stenting) to relieve the underlying obstruction if feasible, alongside symptomatic measures such as emollients and a trial of an agent such as a bile acid sequestrant or sertraline for the itching', true, 'Correct. Pruritus in obstructive jaundice is related to cholestasis and accumulation of bile salts and other pruritogens; where feasible, relieving the biliary obstruction (for example with a stent) is the most effective approach, alongside symptomatic measures such as emollients and specific agents (bile acid sequestrants, or drugs such as sertraline, which have evidence in cholestatic pruritus) when drainage is not possible or insufficient.', 2),
('e2000000-0000-0000-0000-000000000048', 'C', 'Topical corticosteroid cream applied to the whole body', false, 'Ruled out because topical corticosteroids are not the standard treatment for cholestatic pruritus, which is a systemic phenomenon related to bile salt accumulation rather than a localised inflammatory skin condition.', 3),
('e2000000-0000-0000-0000-000000000048', 'D', 'Reassurance only, as pruritus from jaundice cannot be treated', false, 'Ruled out because effective options exist (biliary drainage where feasible, and specific pharmacological agents), so pruritus from cholestasis should not be dismissed as untreatable.', 4),
('e2000000-0000-0000-0000-000000000048', 'E', 'Increase his opioid dose, as this will relieve the itching', false, 'Ruled out because opioids can actually cause or worsen pruritus in some patients (via histamine release or central mechanisms) and are not a treatment for cholestatic pruritus specifically.', 5),
('e2000000-0000-0000-0000-000000000049', 'A', 'Reassure him that dry mouth from opioids and radiotherapy cannot be improved in any way', false, 'Ruled out because simple, effective measures exist to improve comfort from xerostomia and should be actively offered rather than dismissing the symptom as untreatable.', 1),
('e2000000-0000-0000-0000-000000000049', 'B', 'Stop the oxygen therapy immediately regardless of his oxygen requirements', false, 'Ruled out because oxygen should not be stopped purely to address dry mouth without considering his actual oxygen needs; instead, humidification or mouth care measures can be used alongside continued appropriately indicated oxygen therapy.', 2),
('e2000000-0000-0000-0000-000000000049', 'C', 'Regular mouth care (frequent sips of water, ice chips, saliva substitutes, and good oral hygiene), while reviewing whether any contributing medications or oxygen delivery can be adjusted', true, 'Correct. Xerostomia in palliative patients is commonly multifactorial (opioids, radiotherapy to head and neck structures, supplemental oxygen, and other medications with anticholinergic effects), and management centres on regular, proactive mouth care measures such as frequent fluid sips, ice chips, saliva substitutes, and good oral hygiene, alongside reviewing and adjusting contributing factors where possible.', 3),
('e2000000-0000-0000-0000-000000000049', 'D', 'Prescribe a strong anticholinergic medication to help with his symptoms', false, 'Ruled out because anticholinergic medications typically worsen, rather than improve, dry mouth by further reducing salivary secretion.', 4),
('e2000000-0000-0000-0000-000000000049', 'E', 'Restrict his oral fluid intake to reduce the sensation of dryness', false, 'Ruled out because restricting fluids would likely worsen rather than improve xerostomia; regular small sips of fluid are part of standard management.', 5),
('e2000000-0000-0000-0000-000000000050', 'A', 'Reassure her that high-calorie nutritional supplements alone will reverse the weight loss and restore her strength', false, 'Ruled out because cancer cachexia is driven by tumour-related metabolic and inflammatory changes rather than simple calorie deficiency, so nutritional supplementation alone typically has limited effect on reversing the underlying process.', 1),
('e2000000-0000-0000-0000-000000000050', 'B', 'Insist on artificial nutritional support (such as parenteral nutrition) as the standard approach for all patients with cancer cachexia', false, 'Ruled out because artificial nutritional support is not standard or routinely beneficial for most patients with advanced cancer cachexia and carries its own risks and burdens; it is reserved for specific situations rather than used routinely.', 2),
('e2000000-0000-0000-0000-000000000050', 'C', 'Tell her that nothing can be done to help her appetite or symptoms', false, 'Ruled out because while cachexia cannot usually be fully reversed, options such as a trial of corticosteroids can provide meaningful, if temporary, symptomatic benefit, and this should be discussed rather than dismissed.', 3),
('e2000000-0000-0000-0000-000000000050', 'D', 'Explain that this represents cancer-related cachexia rather than simple starvation, exclude other reversible contributing causes, and consider a short trial of a corticosteroid for a limited period to stimulate appetite if this is her main concern', true, 'Correct. Cancer cachexia is a distinct metabolic syndrome (not simply reduced calorie intake) and does not respond in the same way as starvation to nutritional supplementation alone; after excluding other reversible causes of poor appetite (such as poorly controlled pain, nausea, or depression), a short trial of a corticosteroid can provide temporary appetite stimulation and is a recognised, pragmatic option when improving appetite is an important goal for the patient.', 4),
('e2000000-0000-0000-0000-000000000050', 'E', 'Recommend a strict high-fibre, low-fat diet as the definitive treatment', false, 'Ruled out because dietary modification of this kind is not an established treatment for cancer cachexia, which relates to underlying tumour biology rather than dietary composition.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e2000000-0000-0000-0000-000000000001', 'Cheyne-Stokes breathing, mottled peripheries, reduced consciousness and cessation of oral intake are classic features of the dying phase in a patient with known terminal illness.', 1),
('e2000000-0000-0000-0000-000000000001', 'Recognising dying prompts a shift to comfort-focused care: rationalising medications, prescribing anticipatory subcutaneous drugs, and stopping non-essential monitoring.', 2),
('e2000000-0000-0000-0000-000000000001', 'Sensitive, honest communication with family about prognosis is a core part of good end-of-life care.', 3),
('e2000000-0000-0000-0000-000000000002', 'A DNACPR decision is a clinical decision, but a patient with capacity should be involved in the discussion and their wishes given central weight.', 1),
('e2000000-0000-0000-0000-000000000002', 'Relatives cannot consent to or veto a DNACPR decision on behalf of a patient who has capacity; their role differs when the patient lacks capacity.', 2),
('e2000000-0000-0000-0000-000000000002', 'Discussions about resuscitation should not be avoided purely because they may be difficult; they should be handled sensitively and are legally and ethically expected.', 3),
('e2000000-0000-0000-0000-000000000003', 'An Independent Mental Capacity Advocate (IMCA) must be involved in best interests decisions about serious medical treatment when a patient lacks capacity and has no family, friends, attorney or deputy to consult.', 1),
('e2000000-0000-0000-0000-000000000003', 'Best interests decisions are made by the treating clinician (informed by relevant input), not handed entirely to family, care staff, or the courts in routine cases.', 2),
('e2000000-0000-0000-0000-000000000003', 'Court of Protection involvement is reserved for genuinely disputed or highly complex cases, not standard best interests decision-making.', 3),
('e2000000-0000-0000-0000-000000000004', 'Advance care planning should be offered proactively to patients with progressive, life-limiting conditions such as advanced heart failure, not deferred until a crisis.', 1),
('e2000000-0000-0000-0000-000000000004', $x$Tools such as the ReSPECT process document a patient's preferences for care and treatment, including resuscitation status, in a way that travels with them across care settings.$x$, 2),
('e2000000-0000-0000-0000-000000000004', $x$Sharing advance care plans with out-of-hours and ambulance services helps ensure the patient's wishes are honoured if they deteriorate outside normal working hours.$x$, 3),
('e2000000-0000-0000-0000-000000000005', 'Withdrawal of clinically assisted nutrition and hydration is a major, irreversible decision requiring a robust best interests process, particularly when family members disagree.', 1),
('e2000000-0000-0000-0000-000000000005', $x$Family members provide important information about a patient's known wishes and values but do not make the final best interests decision themselves, nor is it decided by majority vote.$x$, 2),
('e2000000-0000-0000-0000-000000000005', 'Seeking clinical ethics or legal advice is appropriate when there is significant disagreement about withdrawing life-sustaining treatment.', 3),
('e2000000-0000-0000-0000-000000000006', 'Clinically assisted hydration in the dying phase should be considered on an individual basis, weighing possible symptom benefit against risks like fluid overload and increased secretions.', 1),
('e2000000-0000-0000-0000-000000000006', 'Mouth care remains an important comfort measure in dying patients irrespective of hydration status.', 2),
('e2000000-0000-0000-0000-000000000006', 'Decisions about hydration and nutrition at the end of life should be made collaboratively with the family, informed by clinical judgement, not dictated solely by the family or withheld from discussion.', 3),
('e2000000-0000-0000-0000-000000000007', 'Hypercalcaemia of malignancy is an important reversible cause of confusion, drowsiness and constipation that can mimic the dying phase.', 1),
('e2000000-0000-0000-0000-000000000007', $x$Before concluding a patient is entering the irreversible dying phase, clinicians should actively consider and, where appropriate and consistent with the patient's wishes, treat reversible contributors.$x$, 2),
('e2000000-0000-0000-0000-000000000007', 'Treatment of hypercalcaemia typically involves rehydration and an intravenous bisphosphonate.', 3),
('e2000000-0000-0000-0000-000000000008', 'Breaking bad news well involves acknowledging emotion, exploring what the patient already knows and wants to know, and giving honest, sensitive information.', 1),
('e2000000-0000-0000-0000-000000000008', 'Prognosis in advanced cancer is uncertain; honesty about this uncertainty is preferable to false precision or false reassurance.', 2),
('e2000000-0000-0000-0000-000000000008', 'Involving the specialist palliative care team can provide ongoing support for a patient coming to terms with a life-limiting diagnosis.', 3),
('e2000000-0000-0000-0000-000000000009', 'Verification of death (confirming death has occurred) is distinct from certification of death (completing the formal cause of death documentation) and is an expected junior doctor competency.', 1),
('e2000000-0000-0000-0000-000000000009', 'Verification typically involves confirming absence of central pulse, heart and breath sounds, and fixed dilated pupils unresponsive to light, with clear documentation.', 2),
('e2000000-0000-0000-0000-000000000009', 'Not all deaths require coroner referral; an expected death from known progressive disease under medical care usually does not.', 3),
('e2000000-0000-0000-0000-000000000010', 'Fast-track continuing healthcare funding allows rapid provision of care packages for patients with a limited prognosis who wish to be cared for outside hospital.', 1),
('e2000000-0000-0000-0000-000000000010', $x$Supporting a patient's preferred place of death requires timely referral to community palliative care and district nursing teams, not delay.$x$, 2),
('e2000000-0000-0000-0000-000000000010', 'Home death is achievable with appropriate support and should not be dismissed as automatically unsafe.', 3),
('e2000000-0000-0000-0000-000000000011', 'Specialist palliative care referral is appropriate for symptoms that are difficult to control with standard measures, or for complex psychosocial or family needs.', 1),
('e2000000-0000-0000-0000-000000000011', 'Palliative care is a multidisciplinary specialty addressing physical, psychological, social and spiritual aspects of care, not solely pain prescribing.', 2),
('e2000000-0000-0000-0000-000000000011', 'Recognising when to escalate beyond generalist management is a key safe-practice skill for junior doctors.', 3),
('e2000000-0000-0000-0000-000000000012', $x$DNACPR decisions are clinical judgements made by the treating team about whether CPR is likely to succeed or is in the patient's best interests; they are not decisions requiring family consent or unanimous family agreement.$x$, 1),
('e2000000-0000-0000-0000-000000000012', 'Family members should be informed and their views considered, but disagreement between relatives does not obligate the team to perform CPR judged clinically inappropriate.', 2),
('e2000000-0000-0000-0000-000000000012', 'Where conflict is significant, escalation to a senior clinician or clinical ethics support (rather than deferring the decision indefinitely) is appropriate.', 3),
('e2000000-0000-0000-0000-000000000013', 'An IMCA must be involved in best interests decisions about serious medical treatment when a patient lacks capacity and there is no attorney, deputy, or family/friend willing and able to be consulted.', 1),
('e2000000-0000-0000-0000-000000000013', 'A family member who explicitly declines involvement should not be pressured into deciding; this does not remove the safeguard requirement for an IMCA.', 2),
('e2000000-0000-0000-0000-000000000013', 'Genuine disagreement between specialties about best interests should prompt a structured multidisciplinary discussion (with ethics or legal input if needed) rather than unilateral action by one team.', 3),
('e2000000-0000-0000-0000-000000000014', 'Subcutaneous morphine is roughly twice as potent as oral morphine, so the 24-hour oral dose is halved when converting to a subcutaneous infusion.', 1),
('e2000000-0000-0000-0000-000000000014', 'The exact conversion ratio must be known from memory; it is never given in the clinical scenario.', 2),
('e2000000-0000-0000-0000-000000000014', 'Always convert using the total 24-hour oral dose, not a single dose, when calculating a syringe driver dose.', 3),
('e2000000-0000-0000-0000-000000000015', 'Oral morphine to subcutaneous diamorphine conversion divides the total 24-hour oral morphine dose by three.', 1),
('e2000000-0000-0000-0000-000000000015', 'Diamorphine is favoured for subcutaneous syringe drivers because of its high solubility, allowing large doses in a small volume.', 2),
('e2000000-0000-0000-0000-000000000015', 'This conversion factor differs from the oral-to-subcutaneous morphine conversion (divide by two); confusing the two is a common and dangerous prescribing error.', 3),
('e2000000-0000-0000-0000-000000000016', 'Oral oxycodone is more potent than oral morphine, so the equivalent oxycodone dose is lower than the numerical morphine dose when switching.', 1),
('e2000000-0000-0000-0000-000000000016', 'Opioid switching is a recognised strategy when side effects (such as vivid dreams, hallucinations or nausea) limit tolerability of one opioid, even if pain control is adequate.', 2),
('e2000000-0000-0000-0000-000000000016', $x$Conversion doses are always a starting estimate; the dose should subsequently be titrated against the patient's response.$x$, 3),
('e2000000-0000-0000-0000-000000000017', 'Weak opioids such as codeine have a ceiling effect; once near the maximum dose, escalating further gives little added analgesic benefit but increases side effects.', 1),
('e2000000-0000-0000-0000-000000000017', 'The WHO analgesic ladder recommends moving from a weak to a strong opioid when pain remains uncontrolled on a weak opioid at an adequate dose.', 2),
('e2000000-0000-0000-0000-000000000017', $x$Strong opioids should be started at a low dose and titrated according to the individual patient's response.$x$, 3),
('e2000000-0000-0000-0000-000000000018', 'Breakthrough (as required) opioid doses are typically calculated as approximately one-sixth of the total 24-hour background opioid dose, given by the same route.', 1),
('e2000000-0000-0000-0000-000000000018', 'A syringe driver providing continuous background analgesia does not remove the need for an appropriately calculated breakthrough dose for episodes of additional pain.', 2),
('e2000000-0000-0000-0000-000000000018', 'Frequent use of breakthrough doses should prompt review and likely upward titration of the background 24-hour dose.', 3),
('e2000000-0000-0000-0000-000000000019', 'Morphine and its close relatives (diamorphine, codeine) produce active metabolites that accumulate in renal impairment, increasing toxicity risk.', 1),
('e2000000-0000-0000-0000-000000000019', 'Oxycodone, fentanyl and alfentanil are generally preferred opioids in significant renal impairment, though all still require cautious dosing.', 2),
('e2000000-0000-0000-0000-000000000019', $x$'Start low, go slow' with close monitoring is especially important for opioid prescribing in renal impairment.$x$, 3),
('e2000000-0000-0000-0000-000000000020', 'Transdermal fentanyl patches have a delayed onset (around 12 hours) and delayed offset, unlike immediate-release oral opioids.', 1),
('e2000000-0000-0000-0000-000000000020', 'When starting a fentanyl patch, the previous regular opioid should be continued for approximately 12 hours to bridge the gap until the patch takes effect.', 2),
('e2000000-0000-0000-0000-000000000020', 'Conversion tables and product literature guide the correct patch strength; the key safety point being tested is the need for overlap cover during onset, not the exact numerical ratio.', 3),
('e2000000-0000-0000-0000-000000000021', 'Myoclonus, pinpoint pupils, drowsiness and reduced respiratory rate in a patient on opioids indicate opioid toxicity, which may be precipitated by acute kidney injury causing metabolite accumulation.', 1),
('e2000000-0000-0000-0000-000000000021', 'In opioid-tolerant patients, naloxone should be given cautiously in small titrated doses (if needed for significant respiratory depression) to avoid precipitating severe pain or acute withdrawal.', 2),
('e2000000-0000-0000-0000-000000000021', 'Managing opioid toxicity involves reducing or stopping the opioid and treating reversible contributing factors such as dehydration and renal impairment.', 3),
('e2000000-0000-0000-0000-000000000022', 'Standard end-of-life anticipatory prescribing covers four symptom domains: pain/breathlessness, respiratory secretions, agitation/restlessness, and nausea/vomiting.', 1),
('e2000000-0000-0000-0000-000000000022', 'Typical drug choices are an opioid, an antimuscarinic (e.g. hyoscine butylbromide), a sedative (e.g. midazolam), and an antiemetic (e.g. levomepromazine or haloperidol).', 2),
('e2000000-0000-0000-0000-000000000022', 'Anticipatory prescribing allows symptoms to be treated promptly by nursing staff without waiting for a doctor to prescribe at the time of need.', 3),
('e2000000-0000-0000-0000-000000000023', 'Local skin reactions at subcutaneous infusion sites are common and are managed by resiting the cannula, not by stopping the medication.', 1),
('e2000000-0000-0000-0000-000000000023', 'Rotating infusion sites (for example between the abdomen, thighs, and upper arms) helps reduce the risk and impact of site reactions.', 2),
('e2000000-0000-0000-0000-000000000023', 'Site reactions can impair drug absorption, so timely resiting also helps maintain effective symptom control.', 3),
('e2000000-0000-0000-0000-000000000024', 'Frequent breakthrough dose requirements indicate that the background opioid dose needs to be increased.', 1),
('e2000000-0000-0000-0000-000000000024', 'The new background dose is calculated from the total opioid used in the preceding 24 hours (background plus breakthrough doses), with the breakthrough dose then recalculated from the new total.', 2),
('e2000000-0000-0000-0000-000000000024', 'Opioid switching is reserved for problems such as toxicity or intolerable side effects, not simply for inadequate initial dosing, which should first be addressed by titration.', 3),
('e2000000-0000-0000-0000-000000000025', $x$The principle of 'start low, go slow' applies particularly to opioid-naive, frail, or elderly patients, who are more sensitive to opioid effects.$x$, 1),
('e2000000-0000-0000-0000-000000000025', 'Transdermal patches and other long-acting preparations are not appropriate as the first opioid used in an opioid-naive patient because of their slow onset/offset and difficulty titrating quickly.', 2),
('e2000000-0000-0000-0000-000000000025', 'Age or frailty alone should not be used to withhold appropriate analgesia, but does warrant cautious dosing.', 3),
('e2000000-0000-0000-0000-000000000026', 'Constipation is an almost universal opioid side effect that does not improve with tolerance, unlike nausea and sedation, which often settle over days.', 1),
('e2000000-0000-0000-0000-000000000026', 'A regular prophylactic laxative (typically combining a stimulant with a softener) should be co-prescribed with regular opioids, avoiding bulk-forming agents.', 2),
('e2000000-0000-0000-0000-000000000026', 'Anticipating and proactively managing common opioid side effects is an important part of safe opioid prescribing.', 3),
('e2000000-0000-0000-0000-000000000027', 'The WHO analgesic ladder is a stepwise approach: non-opioid, then weak opioid (or low-dose strong opioid), then strong opioid, adjusting according to response.', 1),
('e2000000-0000-0000-0000-000000000027', 'Non-opioid analgesics such as paracetamol are typically continued as pain escalates up the ladder rather than stopped.', 2),
('e2000000-0000-0000-0000-000000000027', 'Bone metastases pain has additional treatment options (NSAIDs if not contraindicated, bisphosphonates, radiotherapy) beyond opioid analgesia alone.', 3),
('e2000000-0000-0000-0000-000000000028', 'Neuropathic pain often responds poorly to standard opioid/non-opioid analgesics and instead responds better to specific agents such as amitriptyline, gabapentin, pregabalin, or duloxetine.', 1),
('e2000000-0000-0000-0000-000000000028', 'These neuropathic agents should be started at a low dose and titrated gradually according to response and tolerability.', 2),
('e2000000-0000-0000-0000-000000000028', 'Recognising the neuropathic character of pain (burning, shooting, altered sensation) is key to selecting the correct treatment class.', 3),
('e2000000-0000-0000-0000-000000000029', 'NSAIDs are particularly effective adjuvant analgesics for bone pain due to metastatic disease, when not contraindicated.', 1),
('e2000000-0000-0000-0000-000000000029', 'Localised palliative radiotherapy is an effective, targeted treatment for pain from a discrete bone metastasis.', 2),
('e2000000-0000-0000-0000-000000000029', 'A multimodal approach (opioids, adjuvants, radiotherapy, and consideration of bisphosphonates) is preferred over opioid dose escalation alone for bone pain.', 3),
('e2000000-0000-0000-0000-000000000030', 'NSAIDs carry increased risk of nephrotoxicity in patients with significant renal impairment and increased risk of gastrointestinal bleeding in those with a history of peptic ulcer disease or prior bleeding.', 1),
('e2000000-0000-0000-0000-000000000030', 'The combination of renal impairment and a bleeding ulcer history makes NSAIDs a particularly important drug class to avoid in this patient.', 2),
('e2000000-0000-0000-0000-000000000030', 'Alternative strategies (opioids with dose caution, radiotherapy, neuropathic agents if indicated) remain appropriate even when NSAIDs must be avoided.', 3),
('e2000000-0000-0000-0000-000000000031', $x$The concept of 'total pain' recognises physical, psychological, social and spiritual dimensions contributing to a patient's experience of pain.$x$, 1),
('e2000000-0000-0000-0000-000000000031', 'Addressing total pain requires holistic, multidisciplinary support (for example psychology, social work, chaplaincy) alongside physical symptom management.', 2),
('e2000000-0000-0000-0000-000000000031', 'Escalating analgesia alone is unlikely to fully resolve pain that has significant psychosocial or existential contributors.', 3),
('e2000000-0000-0000-0000-000000000032', 'Incident pain is pain triggered predictably by a specific movement or procedure (such as turning, dressing changes, or weight-bearing), distinct from constant background pain.', 1),
('e2000000-0000-0000-0000-000000000032', 'Incident pain is best managed by giving a fast-acting breakthrough analgesic dose timed to have its peak effect during the anticipated trigger.', 2),
('e2000000-0000-0000-0000-000000000032', 'Increasing the background opioid dose is not the appropriate solution for predictable, brief incident pain, as it risks toxicity between episodes.', 3),
('e2000000-0000-0000-0000-000000000033', 'Red flags for metastatic spinal cord compression include progressive, severe back pain (especially worse at night or lying flat), new limb weakness or gait disturbance, sensory disturbance (such as a sensory level), and upper motor neuron signs.', 1),
('e2000000-0000-0000-0000-000000000033', 'Metastatic spinal cord compression is an oncological emergency requiring urgent MRI, immediate high-dose corticosteroids, and urgent specialist referral to prevent irreversible neurological damage.', 2),
('e2000000-0000-0000-0000-000000000033', 'Delay in diagnosis and treatment is the single biggest determinant of poor neurological outcome in cord compression.', 3),
('e2000000-0000-0000-0000-000000000034', 'Colicky, cramping visceral pain in bowel obstruction is treated with an antimuscarinic antispasmodic such as hyoscine butylbromide.', 1),
('e2000000-0000-0000-0000-000000000034', 'Prokinetic agents and stimulant laxatives should generally be avoided in bowel obstruction as they can worsen colic, vomiting, and potentially risk perforation.', 2),
('e2000000-0000-0000-0000-000000000034', 'Background opioid analgesia is used alongside antispasmodics for overall pain control in malignant bowel obstruction.', 3),
('e2000000-0000-0000-0000-000000000035', 'Liver capsule pain (from stretching of the liver capsule by hepatic metastases or hepatomegaly) characteristically responds to corticosteroids as an adjuvant analgesic.', 1),
('e2000000-0000-0000-0000-000000000035', 'Recognising the specific pain mechanism (capsular stretch versus colic versus bone pain) helps direct the correct choice of adjuvant treatment.', 2),
('e2000000-0000-0000-0000-000000000035', 'Corticosteroids reduce peritumoural oedema and inflammation, which is the basis for their benefit in liver capsule pain.', 3),
('e2000000-0000-0000-0000-000000000036', 'Opioids metabolised by the liver (including codeine and morphine) can accumulate unpredictably in hepatic failure, requiring dose reduction, longer dosing intervals, and close monitoring.', 1),
('e2000000-0000-0000-0000-000000000036', 'NSAIDs and aspirin should generally be avoided in significant liver disease with coagulopathy because of increased bleeding risk and risk of precipitating renal impairment.', 2),
('e2000000-0000-0000-0000-000000000036', 'Paracetamol can often still be used in liver disease but caution and sometimes dose reduction is needed in significant hepatic impairment.', 3),
('e2000000-0000-0000-0000-000000000037', 'Trigeminal neuralgia presents with brief, severe, stabbing unilateral facial pain, often triggered by light touch, chewing, or cold.', 1),
('e2000000-0000-0000-0000-000000000037', 'Carbamazepine is the established first-line pharmacological treatment for trigeminal neuralgia.', 2),
('e2000000-0000-0000-0000-000000000037', 'Opioids and standard analgesics are generally ineffective for this specific neuropathic facial pain syndrome.', 3),
('e2000000-0000-0000-0000-000000000038', 'Increasing pain on weight-bearing and substantial cortical destruction (more than 50% of bone diameter) on imaging are recognised markers of impending pathological fracture in bone metastases.', 1),
('e2000000-0000-0000-0000-000000000038', 'Prophylactic surgical fixation before a fracture occurs generally gives better functional outcomes than fixation performed after a fracture has happened.', 2),
('e2000000-0000-0000-0000-000000000038', 'Radiotherapy has a role in local control and pain relief but does not substitute for orthopaedic assessment when fracture risk is high.', 3),
('e2000000-0000-0000-0000-000000000039', 'Nausea is a common opioid side effect, typically mediated centrally via the chemoreceptor trigger zone, and often improves with tolerance over days to weeks (unlike constipation).', 1),
('e2000000-0000-0000-0000-000000000039', 'First-line antiemetics for opioid-induced nausea include haloperidol and metoclopramide.', 2),
('e2000000-0000-0000-0000-000000000039', 'New symptoms coinciding temporally with a new medication should prompt consideration of a drug side effect before assuming a new underlying pathology.', 3),
('e2000000-0000-0000-0000-000000000040', 'Gastric stasis presents with early satiety, bloating, and small-volume vomiting soon after eating, often with a succussion splash on examination.', 1),
('e2000000-0000-0000-0000-000000000040', 'Prokinetic antiemetics such as metoclopramide are first-line for gastric stasis because they promote gastric emptying.', 2),
('e2000000-0000-0000-0000-000000000040', 'Antimuscarinic/anticholinergic antiemetics (such as cyclizine or hyoscine butylbromide) can worsen gastric stasis and are generally avoided in this specific cause of nausea.', 3),
('e2000000-0000-0000-0000-000000000041', 'Prokinetic antiemetics (metoclopramide, domperidone) should be avoided in complete mechanical bowel obstruction as they can worsen colic and risk perforation.', 1),
('e2000000-0000-0000-0000-000000000041', 'Non-prokinetic antiemetics (such as cyclizine) and antisecretory agents (hyoscine butylbromide, octreotide) are preferred in malignant bowel obstruction.', 2),
('e2000000-0000-0000-0000-000000000041', 'Laxatives are inappropriate in complete bowel obstruction.', 3),
('e2000000-0000-0000-0000-000000000042', 'Death rattle results from retained upper airway secretions in a dying patient who can no longer clear their airway effectively, and is usually more distressing to observers than to the unconscious patient.', 1),
('e2000000-0000-0000-0000-000000000042', 'Repositioning and antimuscarinic drugs (such as hyoscine butylbromide) are first-line management; these prevent further secretion build-up but do not clear existing secretions.', 2),
('e2000000-0000-0000-0000-000000000042', 'Sensitive explanation to the family that the patient is not distressed by the noise is an important part of managing this symptom.', 3),
('e2000000-0000-0000-0000-000000000043', 'Low-dose opioids can reduce the subjective sensation of breathlessness in advanced illness, distinct from their analgesic use.', 1),
('e2000000-0000-0000-0000-000000000043', 'A fan directed at the face is a simple, effective non-pharmacological measure for breathlessness, thought to work via facial trigeminal nerve stimulation.', 2),
('e2000000-0000-0000-0000-000000000043', 'Anxiety and breathlessness commonly form a vicious cycle; addressing anxiety (for example with a low-dose benzodiazepine) can help break this cycle alongside treating the underlying cause.', 3),
('e2000000-0000-0000-0000-000000000044', 'Conservative management of inoperable malignant bowel obstruction relies on antiemetics, antispasmodics, and agents that reduce gastrointestinal secretions (corticosteroids, octreotide).', 1),
('e2000000-0000-0000-0000-000000000044', 'Reducing gastrointestinal secretions pharmacologically can reduce the volume of vomiting and may allow a nasogastric tube to be avoided in many patients.', 2),
('e2000000-0000-0000-0000-000000000044', 'Patient preference (such as wishing to avoid a nasogastric tube) should be incorporated into a conservative symptom-focused management plan where clinically appropriate.', 3),
('e2000000-0000-0000-0000-000000000045', 'Opioid-induced constipation is very common, predictable, and does not improve with tolerance over time, unlike nausea and sedation.', 1),
('e2000000-0000-0000-0000-000000000045', 'A prophylactic laxative should be started proactively when regular opioids are prescribed, not reactively after constipation develops.', 2),
('e2000000-0000-0000-0000-000000000045', 'Bulk-forming laxatives are generally avoided for opioid-induced constipation; stimulant and/or softening laxatives are preferred.', 3),
('e2000000-0000-0000-0000-000000000046', 'Agitation and restlessness, whether labelled as terminal agitation or delirium, often has an identifiable and sometimes reversible cause that should be actively sought.', 1),
('e2000000-0000-0000-0000-000000000046', 'Common reversible contributors include urinary retention, constipation/faecal impaction, uncontrolled pain, hypoxia, infection, and medication effects.', 2),
('e2000000-0000-0000-0000-000000000046', 'Sedative medication may still be needed for distressing agitation, but assessment for treatable causes should not be skipped in favour of sedation alone.', 3),
('e2000000-0000-0000-0000-000000000047', 'Symptomatic malignant ascites is managed with a trial of a diuretic (such as spironolactone) and/or therapeutic paracentesis to relieve pressure symptoms.', 1),
('e2000000-0000-0000-0000-000000000047', 'Paracentesis is considered particularly when symptoms are significant or when diuretics alone provide insufficient relief.', 2),
('e2000000-0000-0000-0000-000000000047', 'Antibiotics and surgical stripping are not standard treatments for uncomplicated malignant ascites.', 3),
('e2000000-0000-0000-0000-000000000048', 'Pruritus in obstructive jaundice relates to cholestasis and accumulation of bile salts and other pruritogens, not primarily to histamine release.', 1),
('e2000000-0000-0000-0000-000000000048', 'Relieving the underlying biliary obstruction (for example with stenting) is the most effective way to address cholestatic pruritus when feasible.', 2),
('e2000000-0000-0000-0000-000000000048', 'Specific symptomatic treatments (such as bile acid sequestrants or sertraline) have evidence in cholestatic pruritus, in contrast to standard antihistamines, which have limited efficacy for this cause.', 3),
('e2000000-0000-0000-0000-000000000049', 'Xerostomia in palliative care is often multifactorial, commonly related to opioids, head and neck radiotherapy, supplemental oxygen, and anticholinergic medications.', 1),
('e2000000-0000-0000-0000-000000000049', 'Management focuses on regular proactive mouth care: frequent fluid sips, ice chips, saliva substitutes, and good oral hygiene.', 2),
('e2000000-0000-0000-0000-000000000049', 'Reviewing and adjusting contributing medications or oxygen delivery (for example with humidification) can help alongside symptomatic mouth care.', 3),
('e2000000-0000-0000-0000-000000000050', 'Cancer cachexia is a distinct metabolic syndrome driven by tumour-related inflammatory and metabolic changes, distinct from simple starvation, and does not reliably respond to nutritional supplementation alone.', 1),
('e2000000-0000-0000-0000-000000000050', 'Reversible contributors to poor appetite (uncontrolled pain, nausea, depression, oral problems) should be excluded or addressed first.', 2),
('e2000000-0000-0000-0000-000000000050', 'A short trial of corticosteroids is a recognised, pragmatic option for temporary appetite stimulation in advanced cancer, though effects are usually time-limited.', 3);
